INSERT INTO `tb_alur_pembelajaran` (`id_alur_pembelajaran`, `id_mata_kuliah`, `id_pertemuan`, `indikator_pembelajaran`, `bahan_kajian`, `aktivitas_perkuliahan`, `pengalaman_belajar`, `kebutuhan_pembelajaran`, `alokasi_waktu`, `deskripsi_tugas`, `created_at`, `updated_at`) VALUES
(1, 1, 1, '<p>Mahasiswa menunjukkan kemampuan awal literasi teknologi dan rekayasa pada konteks irigasi pertanian</p>\r\n', '<p>Literasi Teknologi dan Rekayasa</p>\r\n', '<p>Dosen Memfasilitasi pelaksanaan pretest TEL melalui WBW dan memberikan pengarahan teknis</p>\r\n', '<p>Mengerjakan tes awal literasi teknologi dan rekayasa</p>\r\n', '<p><strong>Instrumen Tes Literasi Teknologi dan Rekayasa</strong></p>\r\n', '-', '<p>Skor Pretest TEL</p>\r\n', '2024-06-28 07:42:42', '2026-07-28 00:42:21'),
(2, 1, 2, '<ul>\r\n	<li>Mahasiswa dapat mengidentifikasi dan mendeskripsikan permasalahan utama yang diangkat berdasarkan isu, fakta lapangan yang merupakan tantangan global, nasional dan lokal secara jelas.</li>\r\n	<li>Mahasiswa dapat mencari sumber referensi (rujukan) sebagai dasar pengetahuan dan data pendukung yang mendasari jawaban.</li>\r\n	<li>Mahasiswa dapat berkontribusi dalam diskusi kelompok menyampaikan hasil analisis mereka secara lisan atau tertulis dengan cara yang terstruktur dan jelas.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Pengenalan fakta lapangan terkait permaslahan irigasi pertanian.</li>\r\n	<li>Presentasi video atau wacana tentang permasalahan distribusi aliran air ke lahan pertanian.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa menyaksikan tampilan fenaomena sains berupa fakta lapangan dari video tentang permasalahan distribusi aliran air ke lahan pertanian.</li>\r\n	<li>Mahasiswa berpartisipasi dalam sesi diskusi untuk mengidentifikasi masalah dan penyebab masalah sesuai dengan&nbsp; topik yang disajikan.</li>\r\n	<li>Mahasiswa mencari sumber referensi (rujukan) sebagai dasar pengetahuan dan data pendukung yang mendasari jawaban di berbagai sumber daya digital (artikel, video, dll.).</li>\r\n</ul>\r\n', '<p><strong>Engage</strong></p>\r\n\r\n<p>Define the problem.</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa&nbsp; berlatih mengidentifikasi&nbsp; dan mendeskripsikan masalah sesuai&nbsp; dengan&nbsp; topik yang disajikan&nbsp; pada vidio melalui Web Based Worksheet.</li>\r\n	<li>Mahasiswa berlatih mencari sumber referensi (rujukan) sebagai dasar pengetahuan dan data pendukung yang mendasari jawaban.</li>\r\n	<li>Mahasiswa berlatih menyampaikan pendapat hasil analisis mereka secara lisan atau tertulis mengenai permasalahan yang telah diidentifikasi.</li>\r\n</ul>\r\n', '<p>Stimulus berupa wacana/artikel/video</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Identifikasi masalah.</li>\r\n	<li>Deskripsi penyebab masalah.</li>\r\n	<li>Pengetahuan dan data pendukung yang mendasari jawaban.</li>\r\n</ol>\r\n', '2024-06-28 07:54:00', '2024-11-13 16:08:54'),
(4, 1, 2, '<ul>\r\n	<li>Mahasiswa mampu menganalisis konsep energi hidrolik, Hukum Pascal, dan Bernoulli serta menentukan alternatif solusi irigasi yang paling sesuai berdasarkan hasil analisis ilmiah.<strong> (CPMK-1, CPMK-4)</strong></li>\r\n</ul>\r\n', '<p>Konsep fluida, energi hidrolik, Hukum Pascal, dan Bernoulli</p>\r\n', '<p>Engage dan Explore</p>\r\n\r\n<p><em>define the problem, plan possible solutions</em></p>\r\n\r\n<p>Menyajikan fenomena permasalahan irigasi melalui video dan studi kasus serta memfasilitasi diskusi dan observasi</p>\r\n', '<p>Mengidentifikasi permasalahan irigasi, merumuskan pertanyaan, dan merencanakan alternatif solusi berdasarkan hasil observasi dan studi literatur<br />\r\n&nbsp;</p>\r\n', '<p>Akses ke fasilitas lapangan seperti pertanian lokal untuk mengamati praktik-praktik pertanian secara langsung.</p>\r\n', '2 x 50 Menit', '<p>Identifikasi masalah &amp; rencana observasi</p>\r\n', '2024-06-28 08:08:46', '2026-07-28 00:46:50'),
(5, 1, 3, '<ul>\r\n	<li>Mahasiswa&nbsp; dapat&nbsp; mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa dapat berdiskusi, berkomunikasi, berkolaborasi dengan rekan-rekan mereka terkait rancangan solusi permasalahan yang dipilih.</li>\r\n	<li>Mahasiswa dapat membuat hipotesis penyelidikan terkait rancangan solusi permasalahan yang telah dipilih.</li>\r\n</ul>\r\n', '<p>Energi hidrolik</p>\r\n\r\n<ul>\r\n	<li>Hukum pascal</li>\r\n	<li>Hukum bernoulli</li>\r\n	<li>Energi kinetaik dan potensial</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa bekerja secara kelompok mencari informasi melalui sumber daya digital (artikel, video, e-book, dll.) terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa membuat hipotesis penyelidikan terkait rancangan solusi permasalahan yang telah dipilih.</li>\r\n</ul>\r\n', '<p><strong>Explain</strong></p>\r\n\r\n<p>Choose the possible solution</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa&nbsp; berlatih&nbsp; mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa berlatih berdiskusi, berkomunikasi, berkolaborasi dengan rekan-rekan mereka terkait rancangan solusi permasalahan yang dipilih.</li>\r\n	<li>Mahasiswa berlatih membuat hipotesis penyelidikan terkait rancangan solusi permasalahan yang telah dipilih.</li>\r\n</ul>\r\n', '<p>Materi pembelajaran, seperti buku teks, artikel ilmiah, dan sumber daya digital lainnya.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Penjelasan pertimbangan pilihan solusi.</li>\r\n	<li>Deskripsi rancangan solusi yang telah dipilih.</li>\r\n</ol>\r\n', '2024-06-28 08:10:21', '2024-11-13 16:31:50'),
(6, 1, 5, '<ul>\r\n	<li>Mahasiwa dapat mendesain prototype sesuai rancangan yang telah dibuat.</li>\r\n	<li>Mahasiswa dapat menguji desain prototype yang telah dibuat.</li>\r\n	<li>Mahasiswa dapat menganalisa hasil pengujian untuk mengidentifikasi kelemahan atau masalah dalam desain prototype yang di buat.</li>\r\n	<li>Mahasiswa dapat merevisi desain prototype yang di buat berdasarkan hasil pengujian dan umpan balik yang diterima.</li>\r\n	<li>Mahasiswa mendesain ulang prototype berdasarkan analisis hasil pengujian dan umpan balik yang diterima untuk meningkatkan desain yang telah di buat.</li>\r\n	<li>Mahasiswa dapat menjelaskan perubahan yang dilakukan serta alasan perubahan.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Teknologi dan alat yang dapat digunakan untuk pengaliran air pada lahan pertanian.</li>\r\n	<li>Penerapan metode pengujian pengaliran air pada lahan pertanian yang efisien.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa membentuk kelompok dan mendesain prototipe sesuai rancangan yang telah dibuat.</li>\r\n	<li>Mahasiswa melakukan pengujian untuk mengidentifikasi kelemahan atau masalah pada desain prototype yang di buat.</li>\r\n	<li>Mahasiswa berdiskusi untuk menganalisa hasil pengujian yang dilakukan.</li>\r\n	<li>Mahasiswa mendesain ulang prototype berdasarkan analisis hasil pengujian dan umpan balik yang diterima untuk meningkatkan desain yang telah di buat.</li>\r\n	<li>Mahasiswa menjelaskan perubahan yang dilakukan &nbsp;berdasarkan hasil pengujian.</li>\r\n	<li>Mahasiswa melakukan pengujian kembali berdasarkan hasil perbaikan prototype yang dibuat.</li>\r\n</ul>\r\n', '<p><strong>Engineering</strong></p>\r\n\r\n<p>Design, test, &amp; redesign</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa berlatih mendesain prototype sesuai rancangan yang telah dibuat.</li>\r\n	<li>Mahasiswa berlatih mengaitkan konsep, teori yang telah dipelajari dengan aplikasi nyata, sehingga memahami relevansi dengan desain prototype yang dibuat.</li>\r\n	<li>Mahasiswa berlatih melakukan pengujian desain prototype yang telah dibuat.</li>\r\n	<li>Mahasiswa berlatih untuk menganalisis hasil pengujian untuk mengidentifikasi kelemahan atau masalah dalam desain prototype yang di buat.</li>\r\n	<li>Mahasiswa berlatih menyajikan dan menjelaskan perubahan yang dilakukan berdasarkan hasil pengujian.</li>\r\n</ul>\r\n', '<p>Akses ke fasilitas laboratorium atau <em>workshop</em> yang dilengkapi dengan peralatan teknologi yang dibutuhkan.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Penilaian hasil kerja rancangan desain prototype.</li>\r\n	<li>Penilaian hasil kerja prosedur pembuatan prototype.</li>\r\n	<li>Penilaian hasil uji coba dan revisi prototype</li>\r\n	<li>Penilaian prototype.</li>\r\n</ol>\r\n', '2024-06-28 08:11:56', '2024-11-13 16:37:29'),
(7, 1, 6, '<ul>\r\n	<li>Mahasiswa dapat menjelaskan solusi dari permasalahan baru yang di sajikan.</li>\r\n	<li>Mahasiswa&nbsp; dapat&nbsp; mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa dapat menghasilkan ide-ide baru atau solusi kreatif dalam menyelesaikan masalah.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Artikel ilmiah, buku, atau sumber digital lainnya yang bisa dijadikan referensi.</li>\r\n	<li>Studi kasus permasalahan irigasi pertanian lainnya.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa menjelaskan solusi dari permasalahan baru yang di sajikan.</li>\r\n	<li>Mahasiswa&nbsp; mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n</ul>\r\n', '<p><strong>Enrich</strong></p>\r\n\r\n<ul>\r\n	<li>Mahasiswa berlatih menjelaskan solusi dari permasalahan baru yang di sajikan.</li>\r\n	<li>Mahasiswa&nbsp; berlatih mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa berlatih menghasilkan ide-ide baru atau solusi kreatif dalam menyelesaikan masalah.</li>\r\n</ul>\r\n', '<p>Rancangan inovasi terbaru terkait topik lain.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Deskripsi penjelasan solusi permasalahan baru.</li>\r\n	<li>Kesesuaian atau relevansi sumber rujukan yang digunakan.</li>\r\n</ol>\r\n', '2024-06-28 08:15:21', '2024-11-13 16:39:58'),
(8, 1, 6, '<ul>\r\n	<li>Mahasiswa dapat menjelaskan manfaat yang diperoleh dari pengalaman pengerjaan proyek.</li>\r\n	<li>Mahasiswa dapat menjelaskan kesulitan yang dihadapi dari pengalaman pengerjaan proyek.</li>\r\n	<li>Mahasiswa dapat menjelaskan upaya yang dilakukan dari kesulitan yang dihadapi dari pengalaman pengerjaan proyek.</li>\r\n	<li>Mahasiswa dapat mengkomunikasikan produk yang dibuat di kelas dan masyarakat terkait.</li>\r\n</ul>\r\n', '<p>Produk yang dibuat.</p>\r\n', '<ul>\r\n	<li>Mahasiswa menjelaskan manfaat yang diperoleh, kesulitan yang dihadapi dan upaya yang dilakukan dari pengalaman belajar.</li>\r\n	<li>Mahasiswa berdiskusi dan membuat presentasi untuk mengkomunikasikan produk yang dikerjakan kepada kelas dan masyarakat terkait.</li>\r\n</ul>\r\n', '<p><strong>Evaluate</strong></p>\r\n\r\n<p>Communicate.</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa berlatih untuk merefleksikan pengalaman belajar mereka.</li>\r\n	<li>Mahasiswa berlatih mempresentasikan produk yang dibuat di depan kelas.</li>\r\n	<li>Mahasiswa berlatih mengkomunikasikan proyek yang dikerjakan kepada masyarakat terkait.</li>\r\n</ul>\r\n', '<p>Penilaian prototype, presentasi mahasiswa.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Refleksi pengalaman apa yang di pelajari.</li>\r\n	<li>Presentasi untuk mengkomunikasikan kepada kelas dan masyarakat.</li>\r\n</ol>\r\n', '2024-06-28 08:16:37', '2024-11-13 16:42:18'),
(9, 1, 7, '<p><strong>Posttest</strong></p>\r\n', '<p><strong>Posttest</strong></p>\r\n', '<p><strong>Posttest</strong></p>\r\n', '<p><strong>Posttest</strong></p>\r\n', '<p><strong>Posttest</strong></p>\r\n', '-', '<p><strong>Posttest</strong></p>\r\n', '2024-06-28 08:17:05', NULL),
(10, 1, 8, '<ul>\r\n	<li>Mahasiswa dapat mengidentifikasi dan mendeskripsikan permasalahan utama yang diangkat berdasarkan isu, fakta lapangan yang merupakan tantangan global, nasional dan lokal secara jelas.</li>\r\n	<li>Mahasiswa dapat mencari sumber referensi (rujukan) sebagai dasar pengetahuan dan data pendukung yang mendasari jawaban.</li>\r\n	<li>Mahasiswa dapat berkontribusi dalam diskusi kelompok menyampaikan hasil analisis mereka secara lisan atau tertulis dengan cara yang terstruktur dan jelas.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Pengenalan permasalahan makanan berbahaya.</li>\r\n	<li>Presentasi video atau wacana tentang makanan berbahaya.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa menyaksikan tampilan fakta ilmiah makanan berbahaya melalui video.</li>\r\n	<li>Mahasiswa berpartisipasi dalam sesi diskusi kelompok untuk mengidentifikasi masalah dan penyebab masalah sesuai dengan&nbsp; topik yang disajikan&nbsp; .</li>\r\n	<li>Mahasiswa mencari sumber referensi (rujukan) sebagai dasar pengetahuan dan data pendukung yang mendasari jawaban di berbagai sumber daya digital (artikel, video, dll.).</li>\r\n</ul>\r\n', '<p><strong>Engage</strong></p>\r\n\r\n<p>Define the problem.</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa&nbsp; berlatih mengidentifikasi&nbsp; dan mendeskripsikan masalah sesuai&nbsp; dengan&nbsp; topik yang disajikan&nbsp; pada vidio melalui Web Based Worksheet.</li>\r\n	<li>Mahasiswa berlatih mencari sumber referensi (rujukan) sebagai dasar pengetahuan dan data pendukung yang mendasari jawaban.</li>\r\n	<li>Mahasiswa berlatih menyampaikan pendapat hasil analisis mereka secara lisan atau tertulis mengenai permasalahan yang telah diidentifikasi.</li>\r\n</ul>\r\n', '<p>Stimulus berupa wacana/artikel/video</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Identifikasi masalah.</li>\r\n	<li>Deskripsi penyebab masalah.</li>\r\n	<li>Pengetahuan dan data pendukung yang mendasari jawaban.</li>\r\n</ol>\r\n', '2024-06-28 08:18:25', '2024-11-13 17:06:59'),
(11, 1, 8, '<ul>\r\n	<li>Mahasiswa dapat menyusun rencana pengamatan mencakup elemen-elemen penting yang harus diamati.</li>\r\n	<li>Mahasiswa dapat mengidentifikasi masalah utama yang dihadapi oleh masysrakat makanan mengandung borak di pasar yang diamati.</li>\r\n	<li>Mahasiswa dapat menganalisis dan memberikan interpretasi berdasarkan data dan informasi yang di peroleh.</li>\r\n	<li>Mahasiswa dapat merencanakan solusi masalah berdasarkan data dan informasi yang di peroleh.</li>\r\n</ul>\r\n', '<p>Zat aditif&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Definisi Zat aditif.</li>\r\n	<li>Jenis zat aditif.&nbsp;&nbsp;&nbsp;&nbsp;</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa menyusun rencana pengamatan yang mencakup elemen-elemen penting yang harus diamati.</li>\r\n	<li>Mahasiswa melakukan kunjungan pasar, mendeskripsikan kondisi makanan tantangan yang dihadapi.</li>\r\n	<li>Mahasiswa melakukan wawancara serta tanya jawab dengan pedagang untuk mendapatkan informasi yang dibutuhkan.</li>\r\n	<li>Mahasiswa mengumpulkan data dan informasi masalah yang ditemukan serta tantangan yang dihadapi.</li>\r\n	<li>Mahasiswa menyajikan rencana solusi untuk masalah yang ditemukan.</li>\r\n</ul>\r\n', '<p><strong>Explore</strong></p>\r\n\r\n<p>Plan possible solutions.</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa berlatih menyusun rencana pengamatan.</li>\r\n	<li>Mahasiwa berlatih merumuskan pertanyaan-pertanyaan kritis yang relevan untuk mendalami permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa berlatih mengumpulkan data dan informasi tentang makanan mengandung borak dan tantangan yang dihadapi.</li>\r\n	<li>Mahasiswa berlatih mendiskusikan dan merencanakan solusi masalah berdasarkan data dan informasi yang di peroleh.</li>\r\n</ul>\r\n', '<p>Akses ke fasilitas lapangan seperti pasar dan warung di lingkungan sekitar.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Ringkasan Rencana pengamatan.</li>\r\n	<li>Deskripsi kondisi makanan yang beredar di pasar.</li>\r\n	<li>Identifikasi masalah.</li>\r\n	<li>Rumusan pertanyaan-pertanyaan yang di ajukan.</li>\r\n	<li>Penyajian bukti-bukti pendukung.</li>\r\n	<li>Ringkasan Rencana solusi.</li>\r\n</ol>\r\n', '2024-06-28 08:19:56', '2024-11-13 17:10:33'),
(12, 1, 9, '<ul>\r\n	<li>Mahasiswa&nbsp; dapat&nbsp; mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa dapat berdiskusi, berkomunikasi, berkolaborasi dengan rekan-rekan mereka terkait rancangan solusi permasalahan yang dipilih.</li>\r\n	<li>Mahasiswa dapat membuat hipotesis penyelidikan terkait rancangan solusi permasalahan yang telah dipilih.</li>\r\n</ul>\r\n', '<p>Boraks Pada makanan</p>\r\n\r\n<ul>\r\n	<li>Struktur kimia dan sifat-sifat fisika-kimia borak.</li>\r\n	<li>Metabolisme.</li>\r\n	<li>Toksik</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa bekerja secara kelompok mencari informasi melalui sumber daya digital (artikel, video, e-book, dll.) terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa membuat hipotesis penyelidikan terkait rancangan solusi permasalahan yang telah dipilih.</li>\r\n</ul>\r\n', '<p><strong>Explain</strong></p>\r\n\r\n<p>Choose the possible solution</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa&nbsp; berlatih&nbsp; mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa berlatih berdiskusi, berkomunikasi, berkolaborasi dengan rekan-rekan mereka terkait rancangan solusi permasalahan yang dipilih.</li>\r\n	<li>Mahasiswa berlatih membuat hipotesis penyelidikan terkait rancangan solusi permasalahan yang telah dipilih.</li>\r\n</ul>\r\n', '<p>Materi pembelajaran yang berkualitas, seperti buku teks, artikel ilmiah, dan sumber daya multimedia.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Penjelasan pertimbangan pilihan solusi.</li>\r\n	<li>Deskripsi rancangan solusi yang telah dipilih.</li>\r\n</ol>\r\n', '2024-06-28 08:21:27', '2024-11-13 17:13:59'),
(13, 1, 10, '<ul>\r\n	<li>Mahasiwa dapat mendesain prototype sesuai rancangan yang telah dibuat.</li>\r\n	<li>Mahasiswa dapat menguji desain prototype yang telah dibuat.</li>\r\n	<li>Mahasiswa dapat menganalisa hasil pengujian untuk mengidentifikasi kelemahan atau masalah dalam desain prototype yang di buat.</li>\r\n	<li>Mahasiswa dapat merevisi desain prototype yang di buat berdasarkan hasil pengujian dan umpan balik yang diterima.</li>\r\n	<li>Mahasiswa mendesain ulang prototype berdasarkan analisis hasil pengujian dan umpan balik yang diterima untuk meningkatkan desain yang telah di buat.</li>\r\n	<li>Mahasiswa dapat menjelaskan perubahan yang dilakukan serta alasan perubahan.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Teknologi dan alat yang dapat digunakan untuk mendeteksi borak pada makanan.</li>\r\n	<li>Penerapan metode pengujian borak yang mudah dan efisien.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa membentuk kelompok dan mendesain prototipe sesuai rancangan yang telah dibuat.</li>\r\n	<li>Mahasiswa melakukan pengujian untuk mengidentifikasi kelemahan atau masalah pada desain prototype yang di buat.</li>\r\n	<li>Mahasiswa berdiskusi untuk menganalisa hasil pengujian yang dilakukan.</li>\r\n	<li>Mahasiswa mendesain ulang prototype berdasarkan analisis hasil pengujian dan umpan balik yang diterima untuk meningkatkan desain yang telah di buat.</li>\r\n	<li>Mahasiswa menjelaskan perubahan yang dilakukan &nbsp;berdasarkan hasil pengujian.</li>\r\n	<li>Mahasiswa melakukan pengujian kembali berdasarkan hasil perbaikan prototype yang dibuat.</li>\r\n</ul>\r\n', '<p><strong>Engineer</strong></p>\r\n\r\n<p>Design, test, &amp; redesign</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa berlatih mendesain prototype sesuai rancangan yang telah dibuat.</li>\r\n	<li>Mahasiswa berlatih mengaitkan konsep, teori yang telah dipelajari dengan aplikasi nyata, sehingga memahami relevansi dengan desain prototype yang dibuat.</li>\r\n	<li>Mahasiswa berlatih melakukan pengujian desain prototype yang telah dibuat.</li>\r\n	<li>Mahasiswa berlatih untuk menganalisis hasil pengujian untuk mengidentifikasi kelemahan atau masalah dalam desain prototype yang di buat.</li>\r\n	<li>Mahasiswa berlatih menyajikan dan menjelaskan perubahan yang dilakukan berdasarkan hasil pengujian.</li>\r\n</ul>\r\n', '<p>Akses ke fasilitas laboratorium atau <em>workshop</em> yang dilengkapi dengan peralatan teknologi yang dibutuhkan.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ul>\r\n	<li>Penilaian hasil kerja rancangan desain prototype.</li>\r\n	<li>Penilaian hasil kerja prosedur pembuatan prototype.</li>\r\n	<li>Penilaian hasil uji coba dan revisi prototype</li>\r\n	<li>Penilaian prototype.</li>\r\n</ul>\r\n', '2024-06-28 08:22:53', '2024-11-13 17:16:08'),
(14, 1, 11, '<ul>\r\n	<li>Mahasiswa dapat menjelaskan solusi dari permasalahan baru yang di sajikan.</li>\r\n	<li>Mahasiswa&nbsp; dapat&nbsp; mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa dapat menghasilkan ide-ide baru atau solusi kreatif dalam menyelesaikan masalah.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Artikel ilmiah, buku, atau sumber lainnya yang bisa dijadikan referensi.</li>\r\n	<li>Studi kasus permasalahan makanan borak dalam kasus lainnya.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa menjelaskan solusi dari permasalahan baru yang di sajikan.</li>\r\n	<li>Mahasiswa&nbsp; mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n</ul>\r\n', '<p><strong>Enrich</strong></p>\r\n\r\n<ul>\r\n	<li>Mahasiswa berlatih menjelaskan solusi dari permasalahan baru yang di sajikan.</li>\r\n	<li>Mahasiswa&nbsp; berlatih mencari informasi terkait rencana solusi dari permasalahan yang ditemukan.</li>\r\n	<li>Mahasiswa berlatih menghasilkan ide-ide baru atau solusi kreatif dalam menyelesaikan masalah.</li>\r\n</ul>\r\n', '<p>Lembar rancangan inovasi terkait topik lain.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Deskripsi penjelasan solusi permasalahan baru.</li>\r\n	<li>Kesesuaian atau relevansi sumber rujukan yang digunakan.</li>\r\n</ol>\r\n', '2024-06-28 08:24:00', '2024-11-13 17:19:14'),
(15, 1, 11, '<ul>\r\n	<li>Mahasiswa dapat menjelaskan manfaat yang diperoleh dari pengalaman pengerjaan proyek.</li>\r\n	<li>Mahasiswa dapat menjelaskan kesulitan yang dihadapi dari pengalaman pengerjaan proyek.</li>\r\n	<li>Mahasiswa dapat menjelaskan upaya yang dilakukan dari kesulitan yang dihadapi dari pengalaman pengerjaan proyek.</li>\r\n	<li>Mahasiswa dapat mengkomunikasikan produk yang dibuat di kelas dan masyarakat terkait.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Produk/prototype yang dibuat.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Mahasiswa menjelaskan manfaat yang diperoleh, kesulitan yang dihadapi dan upaya yang dilakukan dari pengalaman belajar.</li>\r\n	<li>Mahasiswa berdiskusi dan membuat presentasi untuk mengkomunikasikan produk yang dikerjakan kepada kelas dan masyarakat terkait.</li>\r\n</ul>\r\n', '<p><strong>Evaluate</strong></p>\r\n\r\n<p>Communicate.</p>\r\n\r\n<ul>\r\n	<li>Mahasiswa berlatih untuk merefleksikan pengalaman belajar mereka.</li>\r\n	<li>Mahasiswa berlatih mempresentasikan produk yang dibuat di depan kelas.</li>\r\n	<li>Mahasiswa berlatih mengkomunikasikan proyek yang dikerjakan kepada masyarakat terkait.</li>\r\n</ul>\r\n', '<p>Lembar penilaian prototype, presentasi mahasiswa.</p>\r\n', '2 x 50 Menit', '<p>Penilaian hasil kerja mahasiswa yang memuat:</p>\r\n\r\n<ol>\r\n	<li>Refleksi pengalaman apa yang di pelajari.</li>\r\n	<li>Presentasi untuk mengkomunikasikan kepada kelas dan masyarakat.</li>\r\n</ol>\r\n', '2024-06-28 08:25:42', '2024-11-13 17:24:06'),
(16, 1, 12, '<p><strong>Posttes</strong></p>\r\n', '<p><strong>Posttes</strong></p>\r\n', '<p><strong>Posttes</strong></p>\r\n', '<p><strong>Posttes</strong></p>\r\n', '<p><strong>Posttes</strong></p>\r\n', '-', '<p><strong>Posttes</strong></p>\r\n', '2024-06-28 08:26:17', NULL);
