(228, 5, 43, '', '9fa9b17c1fa4ad1b949576c3799e9ba8.pdf', NULL, 80, 'Rujukan yang menjadi dasar jawaban annada masih kurang tepat karena kurang relevansinya', '2025-02-05 15:07:45', '2026-07-27 22:11:47'),
(229, 7, 33, 'Pada tahap awal, kelompok kami melakukan perencanaan yang matang untuk menentukan dimensi dan bahan yang akan digunakan dalam pembuatan pompa hidram.\"\r\n\"Selama proses perakitan, kami berkolaborasi untuk memastikan setiap komponen terpasang dengan benar dan kokoh.\"\r\n\"Setelah selesai dirakit, pompa hidram yang kami buat diuji kinerjanya dengan cara mengalirkan air melalui pipa.', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(230, 8, 33, 'berdasarkan observasi yang sudah kami lakukan di kecamatan tampan, praktek pembuatan pompa hidram di ltakukan untuk mengaliri lahan pertanian 50 x 50 m2, yang di nominasi oleh tanaman bunga.\r\nsumber air berasal dari sistem irigasi parit yang mengalir ke sungai.\r\npompa hidram yang di gunakan memiliki desaign sederhana dengan tinggi jatuh 50cm dan tinggi angka 1m. air yang di pompa di disribusikan ke lahan melalui sistem saluran terbuka', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(231, 9, 33, 'daerah disekitar pengaliran air memiliki akses yang sulit dijangkau dikarenakan arus yang terjal dan banyaknya rumput liar yang berada di pinggir sungai, sehingga sulitnya meletakkan pompa hidram', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(232, 10, 33, 'apakah ibu membutuhkan pompa hidram sehingga memudahkan pengaliran air dari dataran rendah ke dataran tinggi?', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(233, 74, 33, 'solusi yang akan kami lakukaan yaitu dengan cara membersihkan rumput liar yang ada di sekitar aliran air agar memudahkan pembuatan pompa hidram', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(234, 7, 33, 'Pada tahap awal, kelompok kami melakukan perencanaan yang matang untuk menentukan dimensi dan bahan yang akan digunakan dalam pembuatan pompa hidram.\"\r\n\"Selama proses perakitan, kami berkolaborasi untuk memastikan setiap komponen terpasang dengan benar dan kokoh.\"\r\n\"Setelah selesai dirakit, pompa hidram yang kami buat diuji kinerjanya dengan cara mengalirkan air melalui pipa.', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
