(861, 22, 33, 'menyiapkan alat alatnya, mengukur seberapa besar pompa hidran yang ingin dibuat,memotong paralon sesuai ukuran yang ingin dibuat, setelah dipotong di sambungkan dengan oenyampung paralon, buat menjadi dua bagian kanan dan kiri, di tengah tengahya di tambahkan kelep tusen 1 sebagai penghubung antara pipa kanan dan pipa bagian kiri, kemudian di bagian sebelah kiri di tambahkan grest elbow pipa dan ditambahkan paralon kecil dan di letakkan botol bekas dengan posisi terbalik dan di tambahkan penghubung paralon dan di tambahkan oaralon panjang yang untuk menaikkan air ke atas, kemudian di sebelah kanan di tambahkan penghubung paralon dan paralon dan di tambahkan kelep tusen 2 dan di tambahkan ', NULL, NULL, NULL, NULL, '2025-02-06 09:27:06', NULL),
(862, 2, 43, 'Permasalahan yang terlihat adalah air sulit sampai ke sawah karena letaknya lebih tinggi dari sumber air. Petani harus menggunakan mesin pompa agar air dapat naik ke lahan.', NULL, NULL, 90, 'Hasil kerja ananda terkait identifikasi masalah cukup baik', '2025-02-05 15:07:45', '2026-07-27 22:11:47'),
(863, 4, 43, 'Penyebab utama masalah adalah perbedaan ketinggian antara sumber air dan lahan pertanian sehingga diperlukan alat untuk menaikkan air.', NULL, NULL, 85, 'Hasil kerja ananda sudah baik, namun nada masih bisa menggali lagi penyebab maslah ini terjadi', '2025-02-05 15:07:45', '2026-07-27 22:11:47'),
(864, 6, 43, 'Air mengalir dari tempat yang lebih tinggi ke tempat yang lebih rendah karena pengaruh gaya gravitasi. Oleh sebab itu, air tidak dapat mengalir sendiri ke lahan pertanian yang berada di tempat lebih tinggi.', NULL, NULL, 0, '', '2025-02-05 15:07:45', '2026-07-27 22:11:47'),
(865, 5, 43, '', '9fa9b17c1fa4ad1b949576c3799e9ba8.pdf', NULL, 80, 'Rujukan yang menjadi dasar jawaban annada masih kurang tepat karena kurang relevansinya', '2025-02-05 15:07:45', '2026-07-27 22:11:47'),
(866, 7, 33, 'Pada tahap awal, kelompok kami melakukan perencanaan yang matang untuk menentukan dimensi dan bahan yang akan digunakan dalam pembuatan pompa hidram.\"\r\n\"Selama proses perakitan, kami berkolaborasi untuk memastikan setiap komponen terpasang dengan benar dan kokoh.\"\r\n\"Setelah selesai dirakit, pompa hidram yang kami buat diuji kinerjanya dengan cara mengalirkan air melalui pipa.', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(867, 8, 33, 'berdasarkan observasi yang sudah kami lakukan di kecamatan tampan, praktek pembuatan pompa hidram di ltakukan untuk mengaliri lahan pertanian 50 x 50 m2, yang di nominasi oleh tanaman bunga.\r\nsumber air berasal dari sistem irigasi parit yang mengalir ke sungai.\r\npompa hidram yang di gunakan memiliki desaign sederhana dengan tinggi jatuh 50cm dan tinggi angka 1m. air yang di pompa di disribusikan ke lahan melalui sistem saluran terbuka', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL);
INSERT INTO `tb_jawaban_essai` (`id_jawaban_essai`, `id_soal`, `id_user`, `jawaban_text`, `jawaban_file`, `jawaban_gambar`, `nilai`, `feedback`, `created_at`, `updated_at`) VALUES
(868, 9, 33, 'daerah disekitar pengaliran air memiliki akses yang sulit dijangkau dikarenakan arus yang terjal dan banyaknya rumput liar yang berada di pinggir sungai, sehingga sulitnya meletakkan pompa hidram', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(869, 10, 33, 'apakah ibu membutuhkan pompa hidram sehingga memudahkan pengaliran air dari dataran rendah ke dataran tinggi?', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(870, 74, 33, 'solusi yang akan kami lakukaan yaitu dengan cara membersihkan rumput liar yang ada di sekitar aliran air agar memudahkan pembuatan pompa hidram', NULL, NULL, NULL, NULL, '2025-02-05 20:41:59', NULL),
(871, 71, 43, '', '7d6cee1e003b162cfb7eb08bf098361a.pdf', NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-05 15:10:59', '2026-07-27 22:11:47'),
