(1809, 23, 33, 'dengan membuat pompa hidram sesuai referensi dan menguji cobanya kedalam air', NULL, NULL, NULL, NULL, '2025-02-06 09:26:48', NULL),
(1810, 25, 33, 'paralaon sdeharusnya menggunakan penyambug bukan menggunakan lem paralaon dan klep tusen pemasangannya terbalik dan botol brkas seharusnya yang keras sehingga bisa terpompa', NULL, NULL, NULL, NULL, '2025-02-06 09:26:48', NULL),
(1811, 26, 33, 'menggunakan penyambung pipa dan mengganti botol bekas ke yang lebih keras', NULL, NULL, NULL, NULL, '2025-02-06 09:26:48', NULL),
