(2639, 83, 30, 'Sensor Warna TCS3200 = 20.000\r\nJumper = 15000\r\nModul Bluetooth HC-05 = 30000\r\nArduino Uno = 60000', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(2640, 51, 30, '', NULL, 'b2cfb13d5548cdefb7583818db386592.jpg', 90, 'Hasil kerja yang sudah baik, Ananda sudah berusaha dengan keras', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(2641, 54, 38, 'SENSOR  WARNA TCS3200 BERBASIS ARDUINO UNO R3.', NULL, NULL, 80, '', '2025-02-07 23:51:32', '2026-07-28 02:01:25'),
(2642, 55, 38, 'digunakan untuk mendeteksi bahan kimia pada macam macam makanan, namun sistem yang dibuat masih mendeteksi boraks.  Alat ini dirancang untuk mengidentifikasi boraks menggunakan sensor warna TCS3200 sebagai sensor pembaca warna cara kerja sensor warna TCS3200 ini dilakukan secara bertahap yaitu mendeteksi frekuensi warna dasar secara simultan.', NULL, NULL, 90, '', '2025-02-07 23:51:32', '2026-07-28 02:01:25'),
