INSERT INTO `tb_jawaban_essai` (`id_jawaban_essai`, `id_soal`, `id_user`, `jawaban_text`, `jawaban_file`, `jawaban_gambar`, `nilai`, `feedback`, `created_at`, `updated_at`) VALUES
(2939, 70, 36, 'Melalui proyek perancangan dan pembuatan alat deteksi boraks, kelompok kami memperoleh pengetahuan tentang reaksi kimia boraks, prinsip kerja sensor warna, serta cara mengintegrasikan mikrokontroler dan Bluetooth dalam suatu sistem deteksi. Kami juga mengembangkan keterampilan dalam merancang, merakit, memprogram, menguji, menganalisis hasil, dan memperbaiki prototipe berdasarkan data pengujian. Pengalaman tersebut membuat kami memahami bahwa penyelesaian masalah keamanan pangan memerlukan integrasi konsep IPA untuk menjelaskan reaksi kimia dan prinsip sensor, teknologi untuk memanfaatkan perangkat elektronik dan aplikasi digital, rekayasa untuk merancang serta menyempurnakan prototipe melalui proses desain yang berulang, dan matematika untuk mengolah serta menganalisis data hasil pengujian.', NULL, NULL, 95, 'Hasil kerja Anansa sudah baik', '2025-02-09 19:38:50', '2026-07-06 21:22:34'),
(2940, 85, 36, 'Selama proses observasi hingga penyempurnaan prototipe, kelompok kami menghadapi beberapa kendala, seperti menentukan desain yang sesuai, mengintegrasikan sensor dengan mikrokontroler, serta memperoleh hasil deteksi yang stabil. Pada tahap pengujian, pembacaan sensor masih dipengaruhi oleh intensitas cahaya, posisi sampel, dan kondisi lingkungan sehingga hasil belum sepenuhnya konsisten. Selain itu, koneksi Bluetooth dan daya baterai juga belum selalu stabil saat digunakan dalam waktu yang lama. Kendala tersebut disebabkan oleh sensitivitas sensor terhadap perubahan lingkungan, keterbatasan spesifikasi komponen, serta pengalaman kelompok yang masih terbatas dalam merancang dan mengintegrasikan sistem elektronik.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-09 19:38:50', '2026-07-06 21:22:34'),
(2941, 86, 36, 'Kelompok kami mengatasi kendala tersebut dengan melakukan kalibrasi ulang sensor, memperbaiki posisi sensor dan sampel, menyempurnakan rangkaian serta program mikrokontroler, dan melakukan pengujian berulang pada berbagai kondisi.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-09 19:38:50', '2026-07-06 21:22:34'),
(2942, 70, 43, 'Melalui proyek deteksi boraks pada makanan, kami memperoleh pengetahuan bahwa boraks dapat diidentifikasi melalui perubahan reaksi kimia yang dibaca oleh sensor warna. Kami juga memahami bahwa faktor lingkungan seperti cahaya dan kelembapan dapat memengaruhi akurasi hasil deteksi. Selain itu, dapat meningkatkan pemahaman kami dalam penyelesaian masalah keamanan pangan yang membutuhkan integrasi IPA, teknologi, rekayasa, dan matematika secara terpadu untuk menghasilkan solusi yang efektif dan aplikatif', NULL, NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-09 19:59:01', '2026-07-27 22:11:47'),
(2943, 85, 43, 'Selama proses observasi hingga penyempurnaan prototipe alat deteksi boraks, kelompok kami menghadapi beberapa kendala utama. Pada tahap perancangan, kesulitan terjadi dalam menentukan desain posisi sensor, LED, dan sampel yang stabil karena belum memahami sepenuhnya sensitivitas sensor terhadap cahaya dan jarak. Pada tahap pembuatan, kendala muncul saat merakit rangkaian mikrokontroler, sensor, dan modul Bluetooth akibat keterbatasan pengalaman dalam penyolderan dan integrasi komponen.\r\nPada tahap pengujian, masalah utama adalah hasil pembacaan sensor yang kurang stabil karena dipengaruhi cahaya lingkungan, kelembapan, serta posisi sampel yang tidak selalu konsisten. Sementara itu, pada tahap penyempurnaan, kesulitan muncul dalam meningkatkan akurasi dan stabilitas sistem tanpa mengubah prinsip kerja alat, terutama karena keterbatasan komponen dan belum optimalnya kalibrasi sensor.', NULL, NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-09 19:59:01', '2026-07-27 22:11:47'),
(2944, 86, 43, 'Kelompok kami melakukan beberapa upaya untuk mengatasi kendala selama pengembangan prototipe, seperti melakukan kalibrasi ulang sensor, memperbaiki posisi dan jarak sensor-sampel, serta menambahkan pelindung sederhana untuk mengurangi pengaruh cahaya lingkungan. Selain itu, kami juga memperbaiki sambungan rangkaian, menyempurnakan program mikrokontroler agar komunikasi Bluetooth lebih stabil, serta mengoptimalkan penggunaan daya dengan menonaktifkan komponen yang tidak digunakan. Berdasarkan hasil uji lanjutan, solusi yang diterapkan cukup efektif karena terdapat peningkatan pada kestabilan pembacaan dan kecepatan deteksi.', NULL, NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-09 19:59:01', '2026-07-27 22:11:47'),
(2945, 87, 43, '', '01a162748b90b06e8e620e0d2f661f48.pdf', NULL, 95, 'Hasil kerja ananda sudah baik', '2025-02-09 19:59:01', '2026-07-27 22:11:47'),
(2946, 42, 40, 'Sebelum melakukan kunjungan lapangan, kelompok kami menyusun rencana pengamatan. kami akan mencoba menelusuri pasar dekat rumah, Pengamatan difokuskan pada kondisi lingkungan penjualan makanan di lapangan, jenis makanan yang berpotensi mengandung bahan berbahaya, serta indikasi awal yang dapat diamati secara visual seperti warna, tekstur, aroma, dan daya tahan makanan. Selain itu, kami juga mengidentifikasi praktik pengolahan makanan yang dilakukan pedagang serta potensi penggunaan bahan tambahan yang tidak sesuai dengan standar keamanan pangan. kegiatan kami meliputi observasi langsung, wawancara, dan dokumentasi.', NULL, NULL, 90, 'Hasil kerja ananda sudah baik, harap lebh menata kalimat pada jawaban', '2025-02-09 20:13:53', '2026-07-06 21:22:34'),
(2947, 43, 40, 'banyak makanan yang memiliki warna yang tidak lazim, bau yang aneh, serta ketahanan makanan yang cukup lama ada yang sampai bertahun-tahun, namu dengan makanan yang memiliki warna yang menarik membuat konsumen tertarik mengonsumsi makanan tersebut, masyarakat juga memaklumi bahwa makanan yang berbau aneh tersebut dikarenakan sudah lamanya makanan tersebut terpapar udara, dan harganya juga lebih murah, dengan makanan yang memiliki masa simpan yang lama serta mudah di masak membuat masyarakat menganggap makanan tersebut lebih praktis daripada membuat makanan sendiri.', 'e202458dea6f508f3c93b6bbe94a6d1a.pdf', NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-09 20:13:53', '2026-07-06 21:22:34'),
(2949, 45, 40, 'pertanyaan yang akan kami sampaikan ialah \r\n1. Jenis makanan apa saja yang dijual dan bahan apa saja yang digunakan dalam proses pembuatannya?\r\n2. Apakah Bapak/Ibu mengetahui tentang bahan tambahan makanan seperti boraks?\r\n3. Apakah pernah menggunakan bahan tambahan tertentu dalam proses pengolahan makanan? Jika ya, apa alasannya?\r\n4. Apa kesulitan yang sering dihadapi dalam mengenali makanan yang mengandung bahan berbahaya?\r\n5. Apakah pernah mendapatkan sosialisasi atau edukasi mengenai bahan berbahaya dalam makanan dari Dinas Kesehatan atau lainnya?', NULL, NULL, 85, 'Hasil kerja ananda sudah baik, namun pertanyaan wawancara bisa lebih di maksimalkan lagi untuk menggali informasi', '2025-02-09 20:13:53', '2026-07-06 21:22:34'),
(2950, 81, 40, 'Berdasarkan hasil observasi, wawancara, dan pengujian sederhana yang kami lakukan, ditemukan beberapa temuan terkait keamanan pangan di lapangan. Sebagian pedagang belum sepenuhnya memahami risiko penggunaan bahan tambahan berbahaya seperti boraks. Beberapa produk makanan menunjukkan ciri mencurigakan, seperti tekstur terlalu kenyal, daya simpan lebih lama, dan warna tidak konsisten, yang mengindikasikan kemungkinan adanya bahan tambahan berbahaya.\r\nHasil wawancara menunjukkan bahwa pemahaman masyarakat dan pedagang tentang boraks masih terbatas. Sebagian besar hanya mengetahui bahwa boraks berbahaya, tetapi belum memahami ciri makanan yang mengandung boraks maupun dampak kesehatannya. Faktor ekonomi dan kebiasaan juga menjadi penyebab penggunaan bahan tambahan yang tidak aman.\r\nPengujian sederhana menggunakan metode kunyit menunjukkan beberapa sampel mengalami perubahan warna yang mengarah pada dugaan adanya boraks, meskipun hasil ini masih bersifat indikatif dan memerlukan verifikasi laboratorium.\r\nKendala utama dalam deteksi makanan berbahaya meliputi keterbatasan alat uji yang praktis dan akurat, rendahnya pengetahuan masyarakat, serta minimnya sistem pemeriksaan rutin. Temuan ini menunjukkan perlunya inovasi teknologi deteksi pangan yang lebih praktis, akurat, dan mudah digunakan masyarakat.', NULL, NULL, 95, 'Hasil kerja ananda sudah baik', '2025-02-09 20:13:53', '2026-07-06 21:22:34'),
(2951, 82, 40, 'Beberapa alternatif solusi menurut kelompok kami\r\n1. Test kit boraks instan berbasis kertas indikator\r\n2. Alat deteksi boraks portabel berbasis sensor pintar', NULL, NULL, 95, 'Hasil kerja ananda sudah baik', '2025-02-09 20:13:53', '2026-07-06 21:22:34'),
(2952, 72, 40, '', 'ec0cc732c4ee20d96c5e919dec73cc92.pdf', NULL, 85, 'Hasil kerja ananda sudah baik, namun bukti masih kurang, misalkan ketika wawancara dengan pedagang belum terlihat', '2025-02-09 20:13:53', '2026-07-06 21:22:34'),
(2953, 52, 30, 'port sebagai power untuk mengaktifkan alat pendeteksi boraks\r\nsensor warna TCS 3200 untuk mendeteksi adanya kandungan boraks \r\njumper berfungsi untuk menghubungkan komponen satu dengan komponen lainnya\r\nbluetooth HC 05 berfungsi sebagai komponen yang terhubung dengan smartphone \r\nardiuno uno berfungsi untuk mengendalikan alat dan memudahkan dalam memprogram', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(2954, 53, 30, 'Kelompok kami mengembangkan alat deteksi boraks portabel yang dilengkapi dengan sensor warna untuk mendeteksi perubahan warna reagen secara otomatis. Hasil deteksi ditampilkan secara real-time pada layar dan dapat dihubungkan ke smartphone melalui Bluetooth, sehingga pengguna dapat mengetahui hasil pengujian dengan lebih cepat dan mudah. Alat ini juga dirancang dalam ukuran yang ringkas, menggunakan baterai isi ulang, serta dilengkapi casing yang dibuat dari bahan yang mudah ditemukan. Keunggulan inovasi ini dibandingkan alat yang sudah ada adalah proses pembacaan hasil menjadi lebih objektif karena tidak bergantung pada pengamatan visual pengguna. Selain itu, alat memiliki waktu deteksi yang lebih cepat, mudah dioperasikan oleh masyarakat, dan dapat digunakan sebagai skrining awal keamanan makanan secara praktis. Penggunaan casing dari bahan yang mudah diperoleh juga membuat biaya produksi lebih terjangkau, memudahkan proses perakitan dan perawatan, serta memungkinkan alat direplikasi untuk keperluan pendidikan maupun penggunaan di lapangan. Dengan desain yang portabel, ekonomis, dan mudah digunakan.', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(2955, 83, 30, 'Sensor Warna TCS3200 = 20.000\r\nJumper = 15000\r\nModul Bluetooth HC-05 = 30000\r\nArduino Uno = 60000', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(2956, 54, 40, 'Kelompok kami memilih desain prototipe ini karena memiliki bentuk yang portabel, mudah digunakan, dan biaya pembuatannya relatif terjangkau. Prototipe dirancang menggunakan sensor warna dan mikrokontroler sehingga proses deteksi tidak lagi bergantung pada pengamatan visual pengguna. Selain itu, penggunaan casing dari bahan yang mudah diperoleh membuat alat lebih ringan, mudah dirakit, dan sesuai untuk digunakan di laboratorium maupun di lapangan.', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-09 20:27:32', '2026-07-06 21:22:34'),
(2957, 55, 40, 'Tujuanya adalah menghasilkan alat yang mampu mendeteksi adanya kandungan boraks pada makanan secara cepat, praktis, dan aman. Prototipe ini dikembangkan untuk membantu masyarakat melakukan skrining awal terhadap makanan yang diduga mengandung boraks tanpa harus menggunakan peralatan laboratorium yang rumit.', NULL, NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-09 20:27:32', '2026-07-06 21:22:34'),
(2958, 56, 40, 'Alat:\r\nSolder dan timah solder\r\nObeng kecil\r\nTang potong dan tang lancip\r\nCutter\r\nLem tembak (glue gun)\r\nMultimeter (untuk pengecekan rangkaian)\r\nLaptop/komputer (untuk pemrograman mikrokontroler)\r\nKabel USB untuk pemrograman\r\nBor mini atau mini drill (opsional, untuk pembuatan casing)\r\n\r\nBahan/Komponen Elektronik:\r\nMikrokontroler ESP32 (atau Arduino Uno)\r\nSensor warna TCS34725 atau TCS3200\r\nModul Bluetooth (HC-05/HC-06 jika menggunakan Arduino Uno)\r\nLayar OLED/LCD (opsional, untuk menampilkan hasil deteksi)\r\nBuzzer (indikator suara)\r\nLED indikator (merah, hijau, dan kuning)\r\nPush button (tombol pengoperasian)\r\nSakelar ON/OFF\r\nBaterai lithium 18650 atau power bank sebagai sumber daya\r\nModul charger TP4056 (jika menggunakan baterai isi ulang)\r\nKabel jumper\r\nPCB lubang atau breadboard\r\nResistor sesuai kebutuhan', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik, namun perlu menambhakan bahan pengujian dan bahan casing', '2025-02-09 20:27:32', '2026-07-06 21:22:34'),
(2959, 57, 40, 'Langkah-langkah Pembuatan\r\nRangkaian Elektronik:\r\nHubungkan sensor warna TCS3200, modul Bluetooth HC-05, dan komponen lainnya ke Arduino Uno menggunakan kabel jumper.\r\nPastikan semua koneksi sudah benar dan kuat.\r\n\r\nPemrograman Mikrokontroler:\r\nBuat program (skrip) di Arduino IDE untuk membaca data dari sensor warna, memprosesnya, dan mengirimkannya ke modul Bluetooth.\r\nUnggah program ini ke Arduino Uno.\r\n\r\nPengembangan Aplikasi Android:\r\nBuat aplikasi sederhana di Android Studio atau platform pengembangan aplikasi lainnya.\r\nAplikasi ini akan menerima data dari modul Bluetooth dan menampilkannya dalam format yang mudah dibaca (misalnya, teks atau grafik).\r\n\r\nPengujian:\r\nNyalakan rangkaian dan buka aplikasi di smartphone.\r\nLakukan pengujian dengan sampel makanan yang mengandung boraks dan yang tidak.\r\nPastikan alat memberikan hasil yang akurat dan konsisten.', NULL, NULL, 90, 'Langkah yang anda susun sudah baik', '2025-02-09 20:27:32', '2026-07-06 21:22:34'),
(2960, 65, 29, 'Sebelum mencari solusi, penting untuk mengidentifikasi penyebab mengapa stik pendeteksi boraks tidak bertahan lama. Beberapa faktor yang mungkin berperan antara lain:\r\nBaterai,  Baterai yang digunakan mungkin memiliki kapasitas yang kecil atau kualitas yang buruk, sehingga cepat habis.\r\nKonsumsi Daya: Komponen-komponen elektronik, seperti sensor warna atau modul Bluetooth, mungkin mengonsumsi daya yang besar.\r\nDesain Rangkaian, Desain rangkaian yang kurang efisien dapat menyebabkan pemborosan daya.\r\nPenggunaan, Penggunaan yang terlalu sering atau terus-menerus dapat mempercepat habisnya baterai.\r\n\r\nSetelah mengidentifikasi penyebab masalah, berikut adalah beberapa solusi inovatif yang dapat dipertimbangkan:\r\nPenggunaan Baterai Berkapasitas Tinggi:\r\nGanti baterai yang ada dengan baterai yang memiliki kapasitas lebih besar. Baterai lithium-ion atau baterai isi ulang lainnya mungkin bisa menjadi pilihan yang baik.\r\n\r\nPenggunaan Komponen Hemat Daya:\r\nGunakan komponen elektronik yang memiliki konsumsi daya yang lebih rendah, seperti sensor warna atau modul Bluetooth yang hemat energi.\r\n\r\nDesain Rangkaian yang Efisien:\r\nOptimalkan desain rangkaian untuk mengurangi pemborosan daya. Misalnya, gunakan teknik pengaturan daya atau saklar untuk mematikan komponen yang tidak digunakan.\r\n\r\nMode Hemat Daya:\r\nTambahkan fitur mode hemat daya pada perangkat. Mode ini akan secara otomatis mengurangi konsumsi daya saat perangkat tidak digunakan atau dalam kondisi siaga.\r\n\r\nPengisian Daya Nirkabel:\r\nIntegrasikan teknologi pengisian daya nirkabel pada stik pendeteksi boraks. Ini akan memudahkan pengguna untuk mengisi daya perangkat tanpa perlu mencolokkan kabel.\r\n\r\nPanel Surya:\r\nJika memungkinkan, tambahkan panel surya kecil pada perangkat. Panel surya ini dapat membantu mengisi daya baterai saat perangkat terpapar sinar matahari.\r\n\r\nManajemen Daya Baterai:\r\nImplementasikan sistem manajemen daya baterai yang cerdas. Sistem ini akan memantau kondisi baterai dan mengatur penggunaan daya secara efisien.\r\n\r\nPeningkatan Perangkat Lunak:\r\nOptimalkan perangkat lunak (firmware) pada mikrokontroler untuk mengurangi konsumsi daya. Misalnya, gunakan algoritma yang lebih efisien atau kurangi frekuensi clock mikrokontroler.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-10 07:05:47', '2026-07-06 21:22:34'),
(2961, 89, 29, 'Setelah mengidentifikasi penyebab masalah daya tahan, kita dapat merancang solusi inovatif yang menggabungkan beberapa pendekatan untuk mencapai hasil yang optimal. Berikut adalah rancangan solusi yang diusulkan:\r\n1. Pemilihan Komponen Hemat Daya\r\nSensor Warna: Ganti sensor warna TCS3200 dengan sensor warna yang lebih hemat energi, seperti sensor warna berbasis CMOS yang memiliki konsumsi daya lebih rendah.\r\nMikrokontroler: Pilih mikrokontroler dengan arsitektur hemat daya, seperti mikrokontroler ARM Cortex-M0+ atau mikrokontroler MSP430.\r\nModul Bluetooth: Gunakan modul Bluetooth Low Energy (BLE), seperti modul Bluetooth 5.0 atau yang lebih baru. BLE dirancang khusus untuk aplikasi berdaya rendah.\r\n2. Desain Rangkaian yang Efisien\r\nPengaturan Daya: Implementasikan teknik pengaturan daya untuk mematikan komponen yang tidak digunakan. Misalnya, sensor warna dan modul Bluetooth dapat dimatikan saat tidak ada pengujian.\r\nPenggunaan Saklar: Tambahkan saklar fisik atau saklar yang dikendalikan oleh mikrokontroler untuk mematikan daya ke bagian-bagian tertentu dari rangkaian saat perangkat tidak digunakan.\r\nOptimasi PCB: Rancang papan sirkuit cetak (PCB) dengan jalur yang lebih pendek dan komponen yang ditempatkan secara efisien untuk mengurangi kehilangan daya.\r\n3. Manajemen Daya Baterai yang Cerdas\r\nBaterai Berkapasitas Tinggi: Gunakan baterai lithium-ion atau baterai isi ulang lainnya dengan kapasitas yang lebih besar.\r\nSistem Manajemen Baterai (BMS): Integrasikan BMS untuk memantau kondisi baterai, mengoptimalkan pengisian daya, dan mencegah pengosongan baterai yang berlebihan.\r\nAlgoritma Penghematan Daya: Kembangkan algoritma pada mikrokontroler untuk mengatur penggunaan daya secara dinamis berdasarkan kondisi perangkat. Misalnya, kurangi frekuensi clock mikrokontroler saat tidak ada pengujian.\r\n\r\n4. Mode Hemat Daya\r\nMode Tidur: Implementasikan mode tidur atau mode daya rendah saat perangkat tidak digunakan. Dalam mode ini, sebagian besar komponen akan dimatikan atau diatur ke konsumsi daya minimum.\r\nAktivasi Otomatis: Rancang fitur aktivasi otomatis berdasarkan deteksi gerakan atau sinyal dari sensor. Misalnya, perangkat akan otomatis menyala saat terdeteksi gerakan atau saat ada sampel makanan yang akan diuji.\r\n\r\n5. Pengisian Daya Nirkabel dan Panel Surya (Opsional)\r\nPengisian Daya Nirkabel: Integrasikan teknologi pengisian daya nirkabel untuk memudahkan pengisian daya perangkat tanpa kabel.\r\nPanel Surya: Jika memungkinkan, tambahkan panel surya kecil pada perangkat untuk membantu mengisi daya baterai saat perangkat terpapar sinar matahari.\r\n\r\n6. Peningkatan Perangkat Lunak\r\nOptimasi Firmware: Optimalkan perangkat lunak (firmware) pada mikrokontroler untuk mengurangi konsumsi daya. Misalnya, gunakan algoritma yang lebih efisien atau kurangi frekuensi clock mikrokontroler saat tidak ada pengujian.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-10 07:05:47', '2026-07-06 21:22:34'),
(2962, 67, 29, '', '127842330d1f7f81a29466cc9f94cccc.pdf', NULL, 90, 'Hasil kerja Anansa sudah baik, namun sumber rujukan kurang relevan', '2025-02-10 07:05:47', '2026-07-06 21:22:34'),
(2963, 58, 26, 'Langkah 1: Perencanaan dan Desain\r\n1. Tentukan tujuan dan sasaran sistem deteksi boraks.\r\n2. Buat desain sistem yang mencakup komponen-komponen yang diperlukan, seperti sensor RGB, sensor kelembaban tanah, Arduino Nano, dan modul Bluetooth.\r\n3. Tentukan spesifikasi teknis sistem, seperti resolusi sensor, kecepatan pengolahan data, dan jangkauan Bluetooth.\r\n\r\nLangkah 2: Pengumpulan Komponen\r\n1. Beli komponen-komponen yang diperlukan, seperti sensor RGB, sensor kelembaban tanah, Arduino Nano, modul Bluetooth, dan bahan-bahan lainnya.\r\n2. Pastikan komponen-komponen yang dibeli sesuai dengan spesifikasi teknis yang telah ditentukan.\r\n\r\nLangkah 3: Pembuatan Prototype\r\n1. Buat prototype sistem deteksi boraks menggunakan komponen-komponen yang telah dikumpulkan.\r\n2. Pasang sensor RGB, sensor kelembaban tanah, dan Arduino Nano pada prototype.\r\n3. Hubungkan modul Bluetooth dengan Arduino Nano untuk memungkinkan komunikasi dengan perangkat Android.\r\n4. Pasang layar LCD untuk menampilkan hasil deteksi boraks.\r\n\r\nLangkah 4: Pengembangan Perangkat Lunak\r\n1. Buat perangkat lunak untuk mengolah data dari sensor RGB dan sensor kelembaban tanah.\r\n2. Gunakan bahasa pemrograman yang sesuai, seperti C++ atau Python, untuk mengembangkan perangkat lunak.\r\n3. Pastikan perangkat lunak dapat berkomunikasi dengan modul Bluetooth untuk mengirimkan hasil deteksi boraks ke perangkat Android.\r\n\r\nLangkah 5: Pengujian dan Kalibrasi\r\n1. Uji prototype sistem deteksi boraks untuk memastikan bahwa semua komponen berfungsi dengan baik.\r\n2. Kalibrasi sensor RGB dan sensor kelembaban tanah untuk memastikan bahwa hasil deteksi boraks akurat.\r\n3. Pastikan perangkat lunak dapat mengolah data dengan baik dan menampilkan hasil deteksi boraks yang akurat.\r\n\r\nLangkah 6: Pengembangan Aplikasi Android\r\n1. Buat aplikasi Android untuk mengirimkan hasil deteksi boraks dari prototype ke perangkat Android.\r\n2. Gunakan bahasa pemrograman yang sesuai, seperti Java atau Kotlin, untuk mengembangkan aplikasi Android.\r\n3. Pastikan aplikasi Android dapat berkomunikasi dengan modul Bluetooth untuk menerima hasil deteksi boraks dari prototype.\r\n\r\nLangkah 7: Pengujian dan Pemeliharaan\r\n1. Uji aplikasi Android untuk memastikan bahwa aplikasi dapat berfungsi dengan baik dan menampilkan hasil deteksi boraks yang akurat.\r\n2. Pastikan prototype sistem deteksi boraks dapat berfungsi dengan baik dan akurat.\r\n3. Lakukan pemeliharaan rutin untuk memastikan bahwa prototype dan aplikasi Android tetap berfungsi dengan baik.', NULL, NULL, 0, '', '2025-02-09 22:40:45', '2026-06-16 09:49:51'),
(2964, 60, 26, 'Hasil Pengujian\r\n1. Fungsi Deteksi Boraks:\r\n- Sensor RGB dapat mendeteksi perubahan warna yang dihasilkan oleh reaksi kimia boraks.\r\n- Hasil deteksi boraks akurat pada 80% kasus.\r\n2. Komunikasi dengan Aplikasi Android:\r\n- Modul Bluetooth dapat berkomunikasi dengan aplikasi Android.\r\n- Hasil deteksi boraks dapat ditampilkan pada aplikasi Android dengan delay 2 detik.\r\n3. Kinerja Sistem:\r\n- Sistem dapat berjalan selama 5 jam dengan baterai yang terisi penuh.\r\n- Sistem dapat mendeteksi boraks dengan akurasi yang tinggi pada suhu ruangan.\r\n\r\nKekurangan dan Rekomendasi Perbaikan\r\n1. Akurasi Deteksi Boraks: Perlu dilakukan kalibrasi sensor RGB untuk meningkatkan akurasi deteksi boraks.\r\n2. Delay Komunikasi: Perlu dilakukan optimasi kode untuk mengurangi delay komunikasi antara modul Bluetooth dan aplikasi Android.\r\n3. Kinerja Baterai: Perlu dilakukan pengujian untuk meningkatkan kinerja baterai dan memperpanjang waktu operasional sistem.\r\n', NULL, NULL, 0, '', '2025-02-09 22:40:45', '2026-06-16 09:49:51'),
(2965, 61, 26, 'Perubahan Desain\r\n1. Optimasi Desain Sensor RGB: Saya akan mengoptimasi desain sensor RGB untuk meningkatkan akurasi deteksi boraks. Ini dapat dilakukan dengan mengubah posisi sensor, meningkatkan resolusi sensor, atau menggunakan sensor yang lebih akurat.\r\n2. Penambahan Filter: Saya akan menambahkan filter pada sensor RGB untuk mengurangi gangguan cahaya dan meningkatkan akurasi deteksi boraks.\r\n\r\nPerubahan Perangkat Lunak\r\n1. Optimasi Algoritma Deteksi: Saya akan mengoptimasi algoritma deteksi boraks untuk meningkatkan akurasi dan kecepatan deteksi. Ini dapat dilakukan dengan menggunakan teknik machine learning atau mengembangkan algoritma yang lebih akurat.\r\n2. Peningkatan Komunikasi Bluetooth: Saya akan meningkatkan komunikasi Bluetooth antara modul Bluetooth dan aplikasi Android untuk mengurangi delay dan meningkatkan kecepatan transfer data.\r\n\r\nPerubahan Perangkat Keras\r\n1. Penggunaan Baterai yang Lebih Efisien: Saya akan menggunakan baterai yang lebih efisien untuk meningkatkan waktu operasional sistem.\r\n2. Penggunaan Modul yang Lebih Kompak: Saya akan menggunakan modul yang lebih kompak untuk mengurangi ukuran sistem dan meningkatkan portabilitas.\r\n\r\nDengan melakukan perubahan-perubahan tersebut, saya yakin bahwa sistem deteksi boraks berbasis Android dapat menjadi lebih akurat, efisien, dan portabel.', NULL, NULL, 0, '', '2025-02-09 22:40:45', '2026-06-16 09:49:51'),
(2966, 64, 26, 'Berdasarkan hasil uji coba 2, saya dapat menyimpulkan bahwa:\r\n\r\n1. Sistem deteksi boraks berbasis Android memiliki potensi besar: Sistem dapat mendeteksi boraks dengan akurasi yang cukup tinggi (80%).\r\n2. Perlu perbaikan pada akurasi deteksi: Akurasi deteksi boraks masih perlu ditingkatkan untuk memastikan bahwa sistem dapat mendeteksi boraks dengan akurasi yang sangat tinggi.\r\n3. Perlu optimasi pada komunikasi Bluetooth: Komunikasi Bluetooth antara modul Bluetooth dan aplikasi Android perlu dioptimalkan untuk mengurangi delay dan meningkatkan keceatan transfer data.\r\n4. Perlu perbaikan pada kinerja baterai: Kinerja baterai perlu ditingkatkan untuk memastikan bahwa sistem dapat beroperasi selama waktu yang lebih lama.\r\n\r\nDengan demikian, saya dapat menyimpulkan bahwa uji coba 1 telah memberikan informasi yang berharga tentang kekuatan dan kelemahan sistem deteksi boraks berbasis Android, dan bahwa perlu dilakukan perbaikan dan optimasi untuk meningkatkan kinerja sistem.', NULL, NULL, 0, '', '2025-02-09 22:40:45', '2026-06-16 09:49:51'),
(2967, 84, 26, '1. Mendeteksi keberadaan boraks melalui reaksi kimia yang diidentifikasi oleh sensor RGB.\r\n2. Menampilkan hasil deteksi boraks pada layar LCD.\r\n3. Mengirimkan hasil deteksi boraks ke perangkat Android melalui modul Bluetooth.\r\n4. Menggunakan sensor kelembaban tanah untuk memperbaiki akurasi deteksi boraks.\r\n\r\nKelebihan\r\n1. Sistem deteksi boraks yang akurat dan efisien.\r\n2. Penggunaan teknologi Android untuk memudahkan penggunaan dan pemantauan.\r\n3. Kemampuan untuk memperbaiki akurasi deteksi boraks dengan menggunakan sensor kelembaban tanah.\r\n\r\nKekurangan\r\n1. Biaya pengembangan sistem yang relatif tinggi.\r\n2. Ketergantungan pada kualitas sensor dan komponen lainnya.\r\n3. Kemungkinan kesalahan deteksi boraks jika sistem tidak dikalibrasi dengan baik.\r\n', NULL, NULL, 0, '', '2025-02-09 22:40:45', '2026-06-16 09:49:51'),
(2968, 59, 26, '', 'cad368fe8e36872bfca77909d3637978.pdf', NULL, 0, '', '2025-02-09 22:40:45', '2026-06-16 09:49:51'),
(2969, 63, 26, '', 'a7c0ee520738e86646064d0c0e7986d4.pdf', NULL, 0, '', '2025-02-09 22:40:45', '2026-06-16 09:49:51'),
(2970, 52, 30, 'port sebagai power untuk mengaktifkan alat pendeteksi boraks\r\nsensor warna TCS 3200 untuk mendeteksi adanya kandungan boraks \r\njumper berfungsi untuk menghubungkan komponen satu dengan komponen lainnya\r\nbluetooth HC 05 berfungsi sebagai komponen yang terhubung dengan smartphone \r\nardiuno uno berfungsi untuk mengendalikan alat dan memudahkan dalam memprogram', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(2971, 53, 30, 'Kelompok kami mengembangkan alat deteksi boraks portabel yang dilengkapi dengan sensor warna untuk mendeteksi perubahan warna reagen secara otomatis. Hasil deteksi ditampilkan secara real-time pada layar dan dapat dihubungkan ke smartphone melalui Bluetooth, sehingga pengguna dapat mengetahui hasil pengujian dengan lebih cepat dan mudah. Alat ini juga dirancang dalam ukuran yang ringkas, menggunakan baterai isi ulang, serta dilengkapi casing yang dibuat dari bahan yang mudah ditemukan. Keunggulan inovasi ini dibandingkan alat yang sudah ada adalah proses pembacaan hasil menjadi lebih objektif karena tidak bergantung pada pengamatan visual pengguna. Selain itu, alat memiliki waktu deteksi yang lebih cepat, mudah dioperasikan oleh masyarakat, dan dapat digunakan sebagai skrining awal keamanan makanan secara praktis. Penggunaan casing dari bahan yang mudah diperoleh juga membuat biaya produksi lebih terjangkau, memudahkan proses perakitan dan perawatan, serta memungkinkan alat direplikasi untuk keperluan pendidikan maupun penggunaan di lapangan. Dengan desain yang portabel, ekonomis, dan mudah digunakan.', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(2972, 83, 30, 'Sensor Warna TCS3200 = 20.000\r\nJumper = 15000\r\nModul Bluetooth HC-05 = 30000\r\nArduino Uno = 60000', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(2973, 54, 29, 'Kelompok kami memilih desain prototipe ini karena memiliki bentuk yang portabel, mudah digunakan, dan biaya pembuatannya relatif terjangkau. Prototipe dirancang menggunakan sensor warna dan mikrokontroler sehingga proses deteksi tidak lagi bergantung pada pengamatan visual pengguna. Selain itu, penggunaan casing dari bahan yang mudah diperoleh membuat alat lebih ringan, mudah dirakit, dan sesuai untuk digunakan di laboratorium maupun di lapangan.', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-10 06:44:29', '2026-07-06 21:22:34'),
(2974, 55, 29, 'Tujuanya adalah menghasilkan alat yang mampu mendeteksi adanya kandungan boraks pada makanan secara cepat, praktis, dan aman. Prototipe ini dikembangkan untuk membantu masyarakat melakukan skrining awal terhadap makanan yang diduga mengandung boraks tanpa harus menggunakan peralatan laboratorium yang rumit.', NULL, NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-10 06:44:29', '2026-07-06 21:22:34'),
(2975, 56, 29, 'Alat:\r\nSolder dan timah solder\r\nObeng kecil\r\nTang potong dan tang lancip\r\nCutter\r\nLem tembak (glue gun)\r\nMultimeter (untuk pengecekan rangkaian)\r\nLaptop/komputer (untuk pemrograman mikrokontroler)\r\nKabel USB untuk pemrograman\r\nBor mini atau mini drill (opsional, untuk pembuatan casing)\r\n\r\nBahan/Komponen Elektronik:\r\nMikrokontroler ESP32 (atau Arduino Uno)\r\nSensor warna TCS34725 atau TCS3200\r\nModul Bluetooth (HC-05/HC-06 jika menggunakan Arduino Uno)\r\nLayar OLED/LCD (opsional, untuk menampilkan hasil deteksi)\r\nBuzzer (indikator suara)\r\nLED indikator (merah, hijau, dan kuning)\r\nPush button (tombol pengoperasian)\r\nSakelar ON/OFF\r\nBaterai lithium 18650 atau power bank sebagai sumber daya\r\nModul charger TP4056 (jika menggunakan baterai isi ulang)\r\nKabel jumper\r\nPCB lubang atau breadboard\r\nResistor sesuai kebutuhan', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik, namun perlu menambhakan bahan pengujian dan bahan casing', '2025-02-10 06:44:29', '2026-07-06 21:22:34'),
(2976, 57, 29, 'Langkah-langkah Pembuatan\r\nRangkaian Elektronik:\r\nHubungkan sensor warna TCS3200, modul Bluetooth HC-05, dan komponen lainnya ke Arduino Uno menggunakan kabel jumper.\r\nPastikan semua koneksi sudah benar dan kuat.\r\n\r\nPemrograman Mikrokontroler:\r\nBuat program (skrip) di Arduino IDE untuk membaca data dari sensor warna, memprosesnya, dan mengirimkannya ke modul Bluetooth.\r\nUnggah program ini ke Arduino Uno.\r\n\r\nPengembangan Aplikasi Android:\r\nBuat aplikasi sederhana di Android Studio atau platform pengembangan aplikasi lainnya.\r\nAplikasi ini akan menerima data dari modul Bluetooth dan menampilkannya dalam format yang mudah dibaca (misalnya, teks atau grafik).\r\n\r\nPengujian:\r\nNyalakan rangkaian dan buka aplikasi di smartphone.\r\nLakukan pengujian dengan sampel makanan yang mengandung boraks dan yang tidak.\r\nPastikan alat memberikan hasil yang akurat dan konsisten.', NULL, NULL, 90, 'Langkah yang anda susun sudah baik', '2025-02-10 06:44:29', '2026-07-06 21:22:34'),
(2977, 65, 29, 'Sebelum mencari solusi, penting untuk mengidentifikasi penyebab mengapa stik pendeteksi boraks tidak bertahan lama. Beberapa faktor yang mungkin berperan antara lain:\r\nBaterai,  Baterai yang digunakan mungkin memiliki kapasitas yang kecil atau kualitas yang buruk, sehingga cepat habis.\r\nKonsumsi Daya: Komponen-komponen elektronik, seperti sensor warna atau modul Bluetooth, mungkin mengonsumsi daya yang besar.\r\nDesain Rangkaian, Desain rangkaian yang kurang efisien dapat menyebabkan pemborosan daya.\r\nPenggunaan, Penggunaan yang terlalu sering atau terus-menerus dapat mempercepat habisnya baterai.\r\n\r\nSetelah mengidentifikasi penyebab masalah, berikut adalah beberapa solusi inovatif yang dapat dipertimbangkan:\r\nPenggunaan Baterai Berkapasitas Tinggi:\r\nGanti baterai yang ada dengan baterai yang memiliki kapasitas lebih besar. Baterai lithium-ion atau baterai isi ulang lainnya mungkin bisa menjadi pilihan yang baik.\r\n\r\nPenggunaan Komponen Hemat Daya:\r\nGunakan komponen elektronik yang memiliki konsumsi daya yang lebih rendah, seperti sensor warna atau modul Bluetooth yang hemat energi.\r\n\r\nDesain Rangkaian yang Efisien:\r\nOptimalkan desain rangkaian untuk mengurangi pemborosan daya. Misalnya, gunakan teknik pengaturan daya atau saklar untuk mematikan komponen yang tidak digunakan.\r\n\r\nMode Hemat Daya:\r\nTambahkan fitur mode hemat daya pada perangkat. Mode ini akan secara otomatis mengurangi konsumsi daya saat perangkat tidak digunakan atau dalam kondisi siaga.\r\n\r\nPengisian Daya Nirkabel:\r\nIntegrasikan teknologi pengisian daya nirkabel pada stik pendeteksi boraks. Ini akan memudahkan pengguna untuk mengisi daya perangkat tanpa perlu mencolokkan kabel.\r\n\r\nPanel Surya:\r\nJika memungkinkan, tambahkan panel surya kecil pada perangkat. Panel surya ini dapat membantu mengisi daya baterai saat perangkat terpapar sinar matahari.\r\n\r\nManajemen Daya Baterai:\r\nImplementasikan sistem manajemen daya baterai yang cerdas. Sistem ini akan memantau kondisi baterai dan mengatur penggunaan daya secara efisien.\r\n\r\nPeningkatan Perangkat Lunak:\r\nOptimalkan perangkat lunak (firmware) pada mikrokontroler untuk mengurangi konsumsi daya. Misalnya, gunakan algoritma yang lebih efisien atau kurangi frekuensi clock mikrokontroler.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-10 07:05:47', '2026-07-06 21:22:34'),
(2978, 89, 29, 'Setelah mengidentifikasi penyebab masalah daya tahan, kita dapat merancang solusi inovatif yang menggabungkan beberapa pendekatan untuk mencapai hasil yang optimal. Berikut adalah rancangan solusi yang diusulkan:\r\n1. Pemilihan Komponen Hemat Daya\r\nSensor Warna: Ganti sensor warna TCS3200 dengan sensor warna yang lebih hemat energi, seperti sensor warna berbasis CMOS yang memiliki konsumsi daya lebih rendah.\r\nMikrokontroler: Pilih mikrokontroler dengan arsitektur hemat daya, seperti mikrokontroler ARM Cortex-M0+ atau mikrokontroler MSP430.\r\nModul Bluetooth: Gunakan modul Bluetooth Low Energy (BLE), seperti modul Bluetooth 5.0 atau yang lebih baru. BLE dirancang khusus untuk aplikasi berdaya rendah.\r\n2. Desain Rangkaian yang Efisien\r\nPengaturan Daya: Implementasikan teknik pengaturan daya untuk mematikan komponen yang tidak digunakan. Misalnya, sensor warna dan modul Bluetooth dapat dimatikan saat tidak ada pengujian.\r\nPenggunaan Saklar: Tambahkan saklar fisik atau saklar yang dikendalikan oleh mikrokontroler untuk mematikan daya ke bagian-bagian tertentu dari rangkaian saat perangkat tidak digunakan.\r\nOptimasi PCB: Rancang papan sirkuit cetak (PCB) dengan jalur yang lebih pendek dan komponen yang ditempatkan secara efisien untuk mengurangi kehilangan daya.\r\n3. Manajemen Daya Baterai yang Cerdas\r\nBaterai Berkapasitas Tinggi: Gunakan baterai lithium-ion atau baterai isi ulang lainnya dengan kapasitas yang lebih besar.\r\nSistem Manajemen Baterai (BMS): Integrasikan BMS untuk memantau kondisi baterai, mengoptimalkan pengisian daya, dan mencegah pengosongan baterai yang berlebihan.\r\nAlgoritma Penghematan Daya: Kembangkan algoritma pada mikrokontroler untuk mengatur penggunaan daya secara dinamis berdasarkan kondisi perangkat. Misalnya, kurangi frekuensi clock mikrokontroler saat tidak ada pengujian.\r\n\r\n4. Mode Hemat Daya\r\nMode Tidur: Implementasikan mode tidur atau mode daya rendah saat perangkat tidak digunakan. Dalam mode ini, sebagian besar komponen akan dimatikan atau diatur ke konsumsi daya minimum.\r\nAktivasi Otomatis: Rancang fitur aktivasi otomatis berdasarkan deteksi gerakan atau sinyal dari sensor. Misalnya, perangkat akan otomatis menyala saat terdeteksi gerakan atau saat ada sampel makanan yang akan diuji.\r\n\r\n5. Pengisian Daya Nirkabel dan Panel Surya (Opsional)\r\nPengisian Daya Nirkabel: Integrasikan teknologi pengisian daya nirkabel untuk memudahkan pengisian daya perangkat tanpa kabel.\r\nPanel Surya: Jika memungkinkan, tambahkan panel surya kecil pada perangkat untuk membantu mengisi daya baterai saat perangkat terpapar sinar matahari.\r\n\r\n6. Peningkatan Perangkat Lunak\r\nOptimasi Firmware: Optimalkan perangkat lunak (firmware) pada mikrokontroler untuk mengurangi konsumsi daya. Misalnya, gunakan algoritma yang lebih efisien atau kurangi frekuensi clock mikrokontroler saat tidak ada pengujian.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-10 07:05:47', '2026-07-06 21:22:34'),
(2979, 67, 29, '', '127842330d1f7f81a29466cc9f94cccc.pdf', NULL, 90, 'Hasil kerja Anansa sudah baik, namun sumber rujukan kurang relevan', '2025-02-10 07:05:47', '2026-07-06 21:22:34'),
(2980, 42, 29, 'Sebelum melakukan kunjungan lapangan, kelompok kami menyusun rencana pengamatan. kami akan mencoba menelusuri pasar dekat rumah, Pengamatan difokuskan pada kondisi lingkungan penjualan makanan di lapangan, jenis makanan yang berpotensi mengandung bahan berbahaya, serta indikasi awal yang dapat diamati secara visual seperti warna, tekstur, aroma, dan daya tahan makanan. Selain itu, kami juga mengidentifikasi praktik pengolahan makanan yang dilakukan pedagang serta potensi penggunaan bahan tambahan yang tidak sesuai dengan standar keamanan pangan. kegiatan kami meliputi observasi langsung, wawancara, dan dokumentasi.', NULL, NULL, 90, 'Hasil kerja ananda sudah baik, harap lebh menata kalimat pada jawaban', '2025-02-10 07:03:59', '2026-07-06 21:22:34'),
(2981, 43, 29, 'banyak makanan yang memiliki warna yang tidak lazim, bau yang aneh, serta ketahanan makanan yang cukup lama ada yang sampai bertahun-tahun, namu dengan makanan yang memiliki warna yang menarik membuat konsumen tertarik mengonsumsi makanan tersebut, masyarakat juga memaklumi bahwa makanan yang berbau aneh tersebut dikarenakan sudah lamanya makanan tersebut terpapar udara, dan harganya juga lebih murah, dengan makanan yang memiliki masa simpan yang lama serta mudah di masak membuat masyarakat menganggap makanan tersebut lebih praktis daripada membuat makanan sendiri.', 'e202458dea6f508f3c93b6bbe94a6d1a.pdf', NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-10 07:03:59', '2026-07-06 21:22:34'),
(2983, 45, 29, 'pertanyaan yang akan kami sampaikan ialah \r\n1. Jenis makanan apa saja yang dijual dan bahan apa saja yang digunakan dalam proses pembuatannya?\r\n2. Apakah Bapak/Ibu mengetahui tentang bahan tambahan makanan seperti boraks?\r\n3. Apakah pernah menggunakan bahan tambahan tertentu dalam proses pengolahan makanan? Jika ya, apa alasannya?\r\n4. Apa kesulitan yang sering dihadapi dalam mengenali makanan yang mengandung bahan berbahaya?\r\n5. Apakah pernah mendapatkan sosialisasi atau edukasi mengenai bahan berbahaya dalam makanan dari Dinas Kesehatan atau lainnya?', NULL, NULL, 85, 'Hasil kerja ananda sudah baik, namun pertanyaan wawancara bisa lebih di maksimalkan lagi untuk menggali informasi', '2025-02-10 07:03:59', '2026-07-06 21:22:34'),
(2984, 81, 29, 'Berdasarkan hasil observasi, wawancara, dan pengujian sederhana yang kami lakukan, ditemukan beberapa temuan terkait keamanan pangan di lapangan. Sebagian pedagang belum sepenuhnya memahami risiko penggunaan bahan tambahan berbahaya seperti boraks. Beberapa produk makanan menunjukkan ciri mencurigakan, seperti tekstur terlalu kenyal, daya simpan lebih lama, dan warna tidak konsisten, yang mengindikasikan kemungkinan adanya bahan tambahan berbahaya.\r\nHasil wawancara menunjukkan bahwa pemahaman masyarakat dan pedagang tentang boraks masih terbatas. Sebagian besar hanya mengetahui bahwa boraks berbahaya, tetapi belum memahami ciri makanan yang mengandung boraks maupun dampak kesehatannya. Faktor ekonomi dan kebiasaan juga menjadi penyebab penggunaan bahan tambahan yang tidak aman.\r\nPengujian sederhana menggunakan metode kunyit menunjukkan beberapa sampel mengalami perubahan warna yang mengarah pada dugaan adanya boraks, meskipun hasil ini masih bersifat indikatif dan memerlukan verifikasi laboratorium.\r\nKendala utama dalam deteksi makanan berbahaya meliputi keterbatasan alat uji yang praktis dan akurat, rendahnya pengetahuan masyarakat, serta minimnya sistem pemeriksaan rutin. Temuan ini menunjukkan perlunya inovasi teknologi deteksi pangan yang lebih praktis, akurat, dan mudah digunakan masyarakat.', NULL, NULL, 95, 'Hasil kerja ananda sudah baik', '2025-02-10 07:03:59', '2026-07-06 21:22:34'),
(2985, 82, 29, 'Beberapa alternatif solusi menurut kelompok kami\r\n1. Test kit boraks instan berbasis kertas indikator\r\n2. Alat deteksi boraks portabel berbasis sensor pintar', NULL, NULL, 95, 'Hasil kerja ananda sudah baik', '2025-02-10 07:03:59', '2026-07-06 21:22:34'),
(2986, 72, 29, '', '199331ee070c7ac022918e054c0240ad.pdf', NULL, 85, 'Hasil kerja ananda sudah baik, namun bukti masih kurang, misalkan ketika wawancara dengan pedagang belum terlihat', '2025-02-10 07:03:59', '2026-07-06 21:22:34'),
(2987, 65, 30, 'Sebelum mencari solusi, penting untuk mengidentifikasi penyebab mengapa stik pendeteksi boraks tidak bertahan lama. Beberapa faktor yang mungkin berperan antara lain:\r\nBaterai,  Baterai yang digunakan mungkin memiliki kapasitas yang kecil atau kualitas yang buruk, sehingga cepat habis.\r\nKonsumsi Daya: Komponen-komponen elektronik, seperti sensor warna atau modul Bluetooth, mungkin mengonsumsi daya yang besar.\r\nDesain Rangkaian, Desain rangkaian yang kurang efisien dapat menyebabkan pemborosan daya.\r\nPenggunaan, Penggunaan yang terlalu sering atau terus-menerus dapat mempercepat habisnya baterai.\r\n\r\nSetelah mengidentifikasi penyebab masalah, berikut adalah beberapa solusi inovatif yang dapat dipertimbangkan:\r\nPenggunaan Baterai Berkapasitas Tinggi:\r\nGanti baterai yang ada dengan baterai yang memiliki kapasitas lebih besar. Baterai lithium-ion atau baterai isi ulang lainnya mungkin bisa menjadi pilihan yang baik.\r\n\r\nPenggunaan Komponen Hemat Daya:\r\nGunakan komponen elektronik yang memiliki konsumsi daya yang lebih rendah, seperti sensor warna atau modul Bluetooth yang hemat energi.\r\n\r\nDesain Rangkaian yang Efisien:\r\nOptimalkan desain rangkaian untuk mengurangi pemborosan daya. Misalnya, gunakan teknik pengaturan daya atau saklar untuk mematikan komponen yang tidak digunakan.\r\n\r\nMode Hemat Daya:\r\nTambahkan fitur mode hemat daya pada perangkat. Mode ini akan secara otomatis mengurangi konsumsi daya saat perangkat tidak digunakan atau dalam kondisi siaga.\r\n\r\nPengisian Daya Nirkabel:\r\nIntegrasikan teknologi pengisian daya nirkabel pada stik pendeteksi boraks. Ini akan memudahkan pengguna untuk mengisi daya perangkat tanpa perlu mencolokkan kabel.\r\n\r\nPanel Surya:\r\nJika memungkinkan, tambahkan panel surya kecil pada perangkat. Panel surya ini dapat membantu mengisi daya baterai saat perangkat terpapar sinar matahari.\r\n\r\nManajemen Daya Baterai:\r\nImplementasikan sistem manajemen daya baterai yang cerdas. Sistem ini akan memantau kondisi baterai dan mengatur penggunaan daya secara efisien.\r\n\r\nPeningkatan Perangkat Lunak:\r\nOptimalkan perangkat lunak (firmware) pada mikrokontroler untuk mengurangi konsumsi daya. Misalnya, gunakan algoritma yang lebih efisien atau kurangi frekuensi clock mikrokontroler.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-10 09:32:46', '2026-07-06 21:22:34'),
(2988, 89, 30, 'Setelah mengidentifikasi penyebab masalah daya tahan, kita dapat merancang solusi inovatif yang menggabungkan beberapa pendekatan untuk mencapai hasil yang optimal. Berikut adalah rancangan solusi yang diusulkan:\r\n1. Pemilihan Komponen Hemat Daya\r\nSensor Warna: Ganti sensor warna TCS3200 dengan sensor warna yang lebih hemat energi, seperti sensor warna berbasis CMOS yang memiliki konsumsi daya lebih rendah.\r\nMikrokontroler: Pilih mikrokontroler dengan arsitektur hemat daya, seperti mikrokontroler ARM Cortex-M0+ atau mikrokontroler MSP430.\r\nModul Bluetooth: Gunakan modul Bluetooth Low Energy (BLE), seperti modul Bluetooth 5.0 atau yang lebih baru. BLE dirancang khusus untuk aplikasi berdaya rendah.\r\n2. Desain Rangkaian yang Efisien\r\nPengaturan Daya: Implementasikan teknik pengaturan daya untuk mematikan komponen yang tidak digunakan. Misalnya, sensor warna dan modul Bluetooth dapat dimatikan saat tidak ada pengujian.\r\nPenggunaan Saklar: Tambahkan saklar fisik atau saklar yang dikendalikan oleh mikrokontroler untuk mematikan daya ke bagian-bagian tertentu dari rangkaian saat perangkat tidak digunakan.\r\nOptimasi PCB: Rancang papan sirkuit cetak (PCB) dengan jalur yang lebih pendek dan komponen yang ditempatkan secara efisien untuk mengurangi kehilangan daya.\r\n3. Manajemen Daya Baterai yang Cerdas\r\nBaterai Berkapasitas Tinggi: Gunakan baterai lithium-ion atau baterai isi ulang lainnya dengan kapasitas yang lebih besar.\r\nSistem Manajemen Baterai (BMS): Integrasikan BMS untuk memantau kondisi baterai, mengoptimalkan pengisian daya, dan mencegah pengosongan baterai yang berlebihan.\r\nAlgoritma Penghematan Daya: Kembangkan algoritma pada mikrokontroler untuk mengatur penggunaan daya secara dinamis berdasarkan kondisi perangkat. Misalnya, kurangi frekuensi clock mikrokontroler saat tidak ada pengujian.\r\n\r\n4. Mode Hemat Daya\r\nMode Tidur: Implementasikan mode tidur atau mode daya rendah saat perangkat tidak digunakan. Dalam mode ini, sebagian besar komponen akan dimatikan atau diatur ke konsumsi daya minimum.\r\nAktivasi Otomatis: Rancang fitur aktivasi otomatis berdasarkan deteksi gerakan atau sinyal dari sensor. Misalnya, perangkat akan otomatis menyala saat terdeteksi gerakan atau saat ada sampel makanan yang akan diuji.\r\n\r\n5. Pengisian Daya Nirkabel dan Panel Surya (Opsional)\r\nPengisian Daya Nirkabel: Integrasikan teknologi pengisian daya nirkabel untuk memudahkan pengisian daya perangkat tanpa kabel.\r\nPanel Surya: Jika memungkinkan, tambahkan panel surya kecil pada perangkat untuk membantu mengisi daya baterai saat perangkat terpapar sinar matahari.\r\n\r\n6. Peningkatan Perangkat Lunak\r\nOptimasi Firmware: Optimalkan perangkat lunak (firmware) pada mikrokontroler untuk mengurangi konsumsi daya. Misalnya, gunakan algoritma yang lebih efisien atau kurangi frekuensi clock mikrokontroler saat tidak ada pengujian.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-10 09:32:46', '2026-07-06 21:22:34'),
(2989, 67, 30, '', 'ad0517190495db8f4a7069fc4239fdbf.pdf', NULL, 90, 'Hasil kerja Anansa sudah baik, namun sumber rujukan kurang relevan', '2025-02-10 09:32:46', '2026-07-06 21:22:34'),
(2990, 42, 30, 'Sebelum melakukan kunjungan lapangan, kelompok kami menyusun rencana pengamatan. kami akan mencoba menelusuri pasar dekat rumah, Pengamatan difokuskan pada kondisi lingkungan penjualan makanan di lapangan, jenis makanan yang berpotensi mengandung bahan berbahaya, serta indikasi awal yang dapat diamati secara visual seperti warna, tekstur, aroma, dan daya tahan makanan. Selain itu, kami juga mengidentifikasi praktik pengolahan makanan yang dilakukan pedagang serta potensi penggunaan bahan tambahan yang tidak sesuai dengan standar keamanan pangan. kegiatan kami meliputi observasi langsung, wawancara, dan dokumentasi.', NULL, NULL, 90, 'Hasil kerja ananda sudah baik, harap lebh menata kalimat pada jawaban', '2025-02-10 15:54:12', '2026-07-06 21:22:34'),
(2991, 43, 30, 'banyak makanan yang memiliki warna yang tidak lazim, bau yang aneh, serta ketahanan makanan yang cukup lama ada yang sampai bertahun-tahun, namu dengan makanan yang memiliki warna yang menarik membuat konsumen tertarik mengonsumsi makanan tersebut, masyarakat juga memaklumi bahwa makanan yang berbau aneh tersebut dikarenakan sudah lamanya makanan tersebut terpapar udara, dan harganya juga lebih murah, dengan makanan yang memiliki masa simpan yang lama serta mudah di masak membuat masyarakat menganggap makanan tersebut lebih praktis daripada membuat makanan sendiri.', 'e202458dea6f508f3c93b6bbe94a6d1a.pdf', NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-10 15:54:12', '2026-07-06 21:22:34'),
(2993, 45, 30, 'pertanyaan yang akan kami sampaikan ialah \r\n1. Jenis makanan apa saja yang dijual dan bahan apa saja yang digunakan dalam proses pembuatannya?\r\n2. Apakah Bapak/Ibu mengetahui tentang bahan tambahan makanan seperti boraks?\r\n3. Apakah pernah menggunakan bahan tambahan tertentu dalam proses pengolahan makanan? Jika ya, apa alasannya?\r\n4. Apa kesulitan yang sering dihadapi dalam mengenali makanan yang mengandung bahan berbahaya?\r\n5. Apakah pernah mendapatkan sosialisasi atau edukasi mengenai bahan berbahaya dalam makanan dari Dinas Kesehatan atau lainnya?', NULL, NULL, 85, 'Hasil kerja ananda sudah baik, namun pertanyaan wawancara bisa lebih di maksimalkan lagi untuk menggali informasi', '2025-02-10 15:54:12', '2026-07-06 21:22:34');
INSERT INTO `tb_jawaban_essai` (`id_jawaban_essai`, `id_soal`, `id_user`, `jawaban_text`, `jawaban_file`, `jawaban_gambar`, `nilai`, `feedback`, `created_at`, `updated_at`) VALUES
(2994, 81, 30, 'Berdasarkan hasil observasi, wawancara, dan pengujian sederhana yang kami lakukan, ditemukan beberapa temuan terkait keamanan pangan di lapangan. Sebagian pedagang belum sepenuhnya memahami risiko penggunaan bahan tambahan berbahaya seperti boraks. Beberapa produk makanan menunjukkan ciri mencurigakan, seperti tekstur terlalu kenyal, daya simpan lebih lama, dan warna tidak konsisten, yang mengindikasikan kemungkinan adanya bahan tambahan berbahaya.\r\nHasil wawancara menunjukkan bahwa pemahaman masyarakat dan pedagang tentang boraks masih terbatas. Sebagian besar hanya mengetahui bahwa boraks berbahaya, tetapi belum memahami ciri makanan yang mengandung boraks maupun dampak kesehatannya. Faktor ekonomi dan kebiasaan juga menjadi penyebab penggunaan bahan tambahan yang tidak aman.\r\nPengujian sederhana menggunakan metode kunyit menunjukkan beberapa sampel mengalami perubahan warna yang mengarah pada dugaan adanya boraks, meskipun hasil ini masih bersifat indikatif dan memerlukan verifikasi laboratorium.\r\nKendala utama dalam deteksi makanan berbahaya meliputi keterbatasan alat uji yang praktis dan akurat, rendahnya pengetahuan masyarakat, serta minimnya sistem pemeriksaan rutin. Temuan ini menunjukkan perlunya inovasi teknologi deteksi pangan yang lebih praktis, akurat, dan mudah digunakan masyarakat.', NULL, NULL, 95, 'Hasil kerja ananda sudah baik', '2025-02-10 15:54:12', '2026-07-06 21:22:34'),
(2995, 82, 30, 'Beberapa alternatif solusi menurut kelompok kami\r\n1. Test kit boraks instan berbasis kertas indikator\r\n2. Alat deteksi boraks portabel berbasis sensor pintar', NULL, NULL, 95, 'Hasil kerja ananda sudah baik', '2025-02-10 15:54:12', '2026-07-06 21:22:34'),
(2996, 72, 30, '', '08997c7bd3ccca99b9635f5263ed1492.pdf', NULL, 85, 'Hasil kerja ananda sudah baik, namun bukti masih kurang, misalkan ketika wawancara dengan pedagang belum terlihat', '2025-02-10 15:54:12', '2026-07-06 21:22:34'),
(2997, 70, 21, ' manfaat yang di peroleh adalah memberikan perlindungan kesehatan masyarakat dengan adanya alat yang kami design dengan dapat menghindari makanan yang telah diuji yang mengandung boraks, kemudian alat ini juga memudahkan para masyarakat untuk mendeteksi kandungan boraks di dalam makanan dengan mudah dan efisien \r\n', NULL, NULL, NULL, NULL, '2025-02-10 15:54:48', NULL),
(2998, 85, 21, 'Sensitivitas dan Spesifisitas: Alat yang ideal harus mampu mendeteksi boraks pada tingkat konsentrasi rendah yang relevan dengan keamanan pangan. Selain itu, alat tersebut harus spesifik terhadap boraks dan tidak memberikan hasil positif palsu akibat adanya zat lain dalam makanan.\r\nReagen dan Bahan Kimia: Pemilihan reagen dan bahan kimia yang tepat sangat penting. Reagen harus stabil, mudah didapatkan, dan aman untuk digunakan.\r\nDesain Prototipe: Merancang prototipe alat yang praktis, mudah digunakan, dan portabel bisa menjadi tantangan. Alat tersebut idealnya ringkas, ringan, dan tidak memerlukan listrik atau peralatan laboratorium yang rumit.\r\nUji Coba dan Validasi: Alat ini harus diuji coba dan divalidasi secara ketat untuk memastikan keakuratan dan keandalannya. Proses ini mungkin memakan waktu dan memerlukan sumber daya yang signifikan.\r\n', NULL, NULL, NULL, NULL, '2025-02-10 15:54:48', NULL),
(2999, 86, 21, 'Penelitian dan Pengembangan: Melakukan penelitian dan pengembangan yang terus-menerus untuk meningkatkan sensitivitas, spesifisitas, dan kinerja alat.\r\nKolaborasi: Bekerja sama dengan ahli kimia, insinyur, dan profesional kesehatan masyarakat untuk mengembangkan dan menguji alat.\r\nPendanaan: Mencari pendanaan dari pemerintah, organisasi nirlaba, atau investor swasta untuk mendukung pengembangan dan produksi alat.\r\nPendidikan Masyarakat: Mengembangkan program pendidikan masyarakat tentang bahaya boraks dalam makanan dan cara menggunakan alat.\r\n', NULL, NULL, NULL, NULL, '2025-02-10 15:54:48', NULL),
(3000, 87, 21, NULL, '8145c9df76ff7ae6340151343ce6e7e2.docx', NULL, NULL, NULL, '2025-02-10 15:54:48', NULL),
(3001, 52, 30, 'port sebagai power untuk mengaktifkan alat pendeteksi boraks\r\nsensor warna TCS 3200 untuk mendeteksi adanya kandungan boraks \r\njumper berfungsi untuk menghubungkan komponen satu dengan komponen lainnya\r\nbluetooth HC 05 berfungsi sebagai komponen yang terhubung dengan smartphone \r\nardiuno uno berfungsi untuk mengendalikan alat dan memudahkan dalam memprogram', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(3002, 53, 30, 'Kelompok kami mengembangkan alat deteksi boraks portabel yang dilengkapi dengan sensor warna untuk mendeteksi perubahan warna reagen secara otomatis. Hasil deteksi ditampilkan secara real-time pada layar dan dapat dihubungkan ke smartphone melalui Bluetooth, sehingga pengguna dapat mengetahui hasil pengujian dengan lebih cepat dan mudah. Alat ini juga dirancang dalam ukuran yang ringkas, menggunakan baterai isi ulang, serta dilengkapi casing yang dibuat dari bahan yang mudah ditemukan. Keunggulan inovasi ini dibandingkan alat yang sudah ada adalah proses pembacaan hasil menjadi lebih objektif karena tidak bergantung pada pengamatan visual pengguna. Selain itu, alat memiliki waktu deteksi yang lebih cepat, mudah dioperasikan oleh masyarakat, dan dapat digunakan sebagai skrining awal keamanan makanan secara praktis. Penggunaan casing dari bahan yang mudah diperoleh juga membuat biaya produksi lebih terjangkau, memudahkan proses perakitan dan perawatan, serta memungkinkan alat direplikasi untuk keperluan pendidikan maupun penggunaan di lapangan. Dengan desain yang portabel, ekonomis, dan mudah digunakan.', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(3003, 83, 30, 'Sensor Warna TCS3200 = 20.000\r\nJumper = 15000\r\nModul Bluetooth HC-05 = 30000\r\nArduino Uno = 60000', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(3004, 70, 39, 'Manfaat yang di peroleh adalah memberikan perlindungan kesehatan masyarakat dengan adanya alat yang kami design dengan dapat menghindari makanan yang telah diuji yang mengandung boraks, kemudian alat ini juga memudahkan para masyarakat untuk mendeteksi kandungan boraks di dalam makanan dengan mudah dan efisien.', NULL, NULL, NULL, NULL, '2025-02-10 15:55:55', NULL),
(3005, 85, 39, 'Sensitivitas dan Spesifisitas: Alat yang ideal harus mampu mendeteksi boraks pada tingkat konsentrasi rendah yang relevan dengan keamanan pangan. Selain itu, alat tersebut harus spesifik terhadap boraks dan tidak memberikan hasil positif palsu akibat adanya zat lain dalam makanan.\r\nReagen dan Bahan Kimia: Pemilihan reagen dan bahan kimia yang tepat sangat penting. Reagen harus stabil, mudah didapatkan, dan aman untuk digunakan.\r\nDesain Prototipe: Merancang prototipe alat yang praktis, mudah digunakan, dan portabel bisa menjadi tantangan. Alat tersebut idealnya ringkas, ringan, dan tidak memerlukan listrik atau peralatan laboratorium yang rumit.\r\nUji Coba dan Validasi: Alat ini harus diuji coba dan divalidasi secara ketat untuk memastikan keakuratan dan keandalannya. Proses ini mungkin memakan waktu dan memerlukan sumber daya yang signifikan.', NULL, NULL, NULL, NULL, '2025-02-10 15:55:55', NULL),
(3006, 86, 39, 'Penelitian dan Pengembangan: Melakukan penelitian dan pengembangan yang terus-menerus untuk meningkatkan sensitivitas, spesifisitas, dan kinerja alat.\r\nKolaborasi: Bekerja sama dengan ahli kimia, insinyur, dan profesional kesehatan masyarakat untuk mengembangkan dan menguji alat.\r\nPendanaan: Mencari pendanaan dari pemerintah, organisasi nirlaba, atau investor swasta untuk mendukung pengembangan dan produksi alat.\r\nPendidikan Masyarakat: Mengembangkan program pendidikan masyarakat tentang bahaya boraks dalam makanan dan cara menggunakan alat.', NULL, NULL, NULL, NULL, '2025-02-10 15:55:55', NULL),
(3007, 87, 39, NULL, '18d945cfa1b58ef7de8c7864b4e797f2.docx', NULL, NULL, NULL, '2025-02-10 15:55:55', NULL),
(3008, 54, 30, 'Kelompok kami memilih desain prototipe ini karena memiliki bentuk yang portabel, mudah digunakan, dan biaya pembuatannya relatif terjangkau. Prototipe dirancang menggunakan sensor warna dan mikrokontroler sehingga proses deteksi tidak lagi bergantung pada pengamatan visual pengguna. Selain itu, penggunaan casing dari bahan yang mudah diperoleh membuat alat lebih ringan, mudah dirakit, dan sesuai untuk digunakan di laboratorium maupun di lapangan.', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-10 15:58:30', '2026-07-06 21:22:34'),
(3009, 55, 30, 'Tujuanya adalah menghasilkan alat yang mampu mendeteksi adanya kandungan boraks pada makanan secara cepat, praktis, dan aman. Prototipe ini dikembangkan untuk membantu masyarakat melakukan skrining awal terhadap makanan yang diduga mengandung boraks tanpa harus menggunakan peralatan laboratorium yang rumit.', NULL, NULL, 90, 'Hasil kerja ananda sudah baik', '2025-02-10 15:58:30', '2026-07-06 21:22:34'),
(3010, 56, 30, 'Alat:\r\nSolder dan timah solder\r\nObeng kecil\r\nTang potong dan tang lancip\r\nCutter\r\nLem tembak (glue gun)\r\nMultimeter (untuk pengecekan rangkaian)\r\nLaptop/komputer (untuk pemrograman mikrokontroler)\r\nKabel USB untuk pemrograman\r\nBor mini atau mini drill (opsional, untuk pembuatan casing)\r\n\r\nBahan/Komponen Elektronik:\r\nMikrokontroler ESP32 (atau Arduino Uno)\r\nSensor warna TCS34725 atau TCS3200\r\nModul Bluetooth (HC-05/HC-06 jika menggunakan Arduino Uno)\r\nLayar OLED/LCD (opsional, untuk menampilkan hasil deteksi)\r\nBuzzer (indikator suara)\r\nLED indikator (merah, hijau, dan kuning)\r\nPush button (tombol pengoperasian)\r\nSakelar ON/OFF\r\nBaterai lithium 18650 atau power bank sebagai sumber daya\r\nModul charger TP4056 (jika menggunakan baterai isi ulang)\r\nKabel jumper\r\nPCB lubang atau breadboard\r\nResistor sesuai kebutuhan', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik, namun perlu menambhakan bahan pengujian dan bahan casing', '2025-02-10 15:58:30', '2026-07-06 21:22:34'),
(3011, 57, 30, 'Langkah-langkah Pembuatan\r\nRangkaian Elektronik:\r\nHubungkan sensor warna TCS3200, modul Bluetooth HC-05, dan komponen lainnya ke Arduino Uno menggunakan kabel jumper.\r\nPastikan semua koneksi sudah benar dan kuat.\r\n\r\nPemrograman Mikrokontroler:\r\nBuat program (skrip) di Arduino IDE untuk membaca data dari sensor warna, memprosesnya, dan mengirimkannya ke modul Bluetooth.\r\nUnggah program ini ke Arduino Uno.\r\n\r\nPengembangan Aplikasi Android:\r\nBuat aplikasi sederhana di Android Studio atau platform pengembangan aplikasi lainnya.\r\nAplikasi ini akan menerima data dari modul Bluetooth dan menampilkannya dalam format yang mudah dibaca (misalnya, teks atau grafik).\r\n\r\nPengujian:\r\nNyalakan rangkaian dan buka aplikasi di smartphone.\r\nLakukan pengujian dengan sampel makanan yang mengandung boraks dan yang tidak.\r\nPastikan alat memberikan hasil yang akurat dan konsisten.', NULL, NULL, 90, 'Langkah yang anda susun sudah baik', '2025-02-10 15:58:30', '2026-07-06 21:22:34'),
(3012, 65, 40, 'Sebelum mencari solusi, penting untuk mengidentifikasi penyebab mengapa stik pendeteksi boraks tidak bertahan lama. Beberapa faktor yang mungkin berperan antara lain:\r\nBaterai,  Baterai yang digunakan mungkin memiliki kapasitas yang kecil atau kualitas yang buruk, sehingga cepat habis.\r\nKonsumsi Daya: Komponen-komponen elektronik, seperti sensor warna atau modul Bluetooth, mungkin mengonsumsi daya yang besar.\r\nDesain Rangkaian, Desain rangkaian yang kurang efisien dapat menyebabkan pemborosan daya.\r\nPenggunaan, Penggunaan yang terlalu sering atau terus-menerus dapat mempercepat habisnya baterai.\r\n\r\nSetelah mengidentifikasi penyebab masalah, berikut adalah beberapa solusi inovatif yang dapat dipertimbangkan:\r\nPenggunaan Baterai Berkapasitas Tinggi:\r\nGanti baterai yang ada dengan baterai yang memiliki kapasitas lebih besar. Baterai lithium-ion atau baterai isi ulang lainnya mungkin bisa menjadi pilihan yang baik.\r\n\r\nPenggunaan Komponen Hemat Daya:\r\nGunakan komponen elektronik yang memiliki konsumsi daya yang lebih rendah, seperti sensor warna atau modul Bluetooth yang hemat energi.\r\n\r\nDesain Rangkaian yang Efisien:\r\nOptimalkan desain rangkaian untuk mengurangi pemborosan daya. Misalnya, gunakan teknik pengaturan daya atau saklar untuk mematikan komponen yang tidak digunakan.\r\n\r\nMode Hemat Daya:\r\nTambahkan fitur mode hemat daya pada perangkat. Mode ini akan secara otomatis mengurangi konsumsi daya saat perangkat tidak digunakan atau dalam kondisi siaga.\r\n\r\nPengisian Daya Nirkabel:\r\nIntegrasikan teknologi pengisian daya nirkabel pada stik pendeteksi boraks. Ini akan memudahkan pengguna untuk mengisi daya perangkat tanpa perlu mencolokkan kabel.\r\n\r\nPanel Surya:\r\nJika memungkinkan, tambahkan panel surya kecil pada perangkat. Panel surya ini dapat membantu mengisi daya baterai saat perangkat terpapar sinar matahari.\r\n\r\nManajemen Daya Baterai:\r\nImplementasikan sistem manajemen daya baterai yang cerdas. Sistem ini akan memantau kondisi baterai dan mengatur penggunaan daya secara efisien.\r\n\r\nPeningkatan Perangkat Lunak:\r\nOptimalkan perangkat lunak (firmware) pada mikrokontroler untuk mengurangi konsumsi daya. Misalnya, gunakan algoritma yang lebih efisien atau kurangi frekuensi clock mikrokontroler.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-10 21:04:40', '2026-07-06 21:22:34'),
(3013, 89, 40, 'Setelah mengidentifikasi penyebab masalah daya tahan, kita dapat merancang solusi inovatif yang menggabungkan beberapa pendekatan untuk mencapai hasil yang optimal. Berikut adalah rancangan solusi yang diusulkan:\r\n1. Pemilihan Komponen Hemat Daya\r\nSensor Warna: Ganti sensor warna TCS3200 dengan sensor warna yang lebih hemat energi, seperti sensor warna berbasis CMOS yang memiliki konsumsi daya lebih rendah.\r\nMikrokontroler: Pilih mikrokontroler dengan arsitektur hemat daya, seperti mikrokontroler ARM Cortex-M0+ atau mikrokontroler MSP430.\r\nModul Bluetooth: Gunakan modul Bluetooth Low Energy (BLE), seperti modul Bluetooth 5.0 atau yang lebih baru. BLE dirancang khusus untuk aplikasi berdaya rendah.\r\n2. Desain Rangkaian yang Efisien\r\nPengaturan Daya: Implementasikan teknik pengaturan daya untuk mematikan komponen yang tidak digunakan. Misalnya, sensor warna dan modul Bluetooth dapat dimatikan saat tidak ada pengujian.\r\nPenggunaan Saklar: Tambahkan saklar fisik atau saklar yang dikendalikan oleh mikrokontroler untuk mematikan daya ke bagian-bagian tertentu dari rangkaian saat perangkat tidak digunakan.\r\nOptimasi PCB: Rancang papan sirkuit cetak (PCB) dengan jalur yang lebih pendek dan komponen yang ditempatkan secara efisien untuk mengurangi kehilangan daya.\r\n3. Manajemen Daya Baterai yang Cerdas\r\nBaterai Berkapasitas Tinggi: Gunakan baterai lithium-ion atau baterai isi ulang lainnya dengan kapasitas yang lebih besar.\r\nSistem Manajemen Baterai (BMS): Integrasikan BMS untuk memantau kondisi baterai, mengoptimalkan pengisian daya, dan mencegah pengosongan baterai yang berlebihan.\r\nAlgoritma Penghematan Daya: Kembangkan algoritma pada mikrokontroler untuk mengatur penggunaan daya secara dinamis berdasarkan kondisi perangkat. Misalnya, kurangi frekuensi clock mikrokontroler saat tidak ada pengujian.\r\n\r\n4. Mode Hemat Daya\r\nMode Tidur: Implementasikan mode tidur atau mode daya rendah saat perangkat tidak digunakan. Dalam mode ini, sebagian besar komponen akan dimatikan atau diatur ke konsumsi daya minimum.\r\nAktivasi Otomatis: Rancang fitur aktivasi otomatis berdasarkan deteksi gerakan atau sinyal dari sensor. Misalnya, perangkat akan otomatis menyala saat terdeteksi gerakan atau saat ada sampel makanan yang akan diuji.\r\n\r\n5. Pengisian Daya Nirkabel dan Panel Surya (Opsional)\r\nPengisian Daya Nirkabel: Integrasikan teknologi pengisian daya nirkabel untuk memudahkan pengisian daya perangkat tanpa kabel.\r\nPanel Surya: Jika memungkinkan, tambahkan panel surya kecil pada perangkat untuk membantu mengisi daya baterai saat perangkat terpapar sinar matahari.\r\n\r\n6. Peningkatan Perangkat Lunak\r\nOptimasi Firmware: Optimalkan perangkat lunak (firmware) pada mikrokontroler untuk mengurangi konsumsi daya. Misalnya, gunakan algoritma yang lebih efisien atau kurangi frekuensi clock mikrokontroler saat tidak ada pengujian.', NULL, NULL, 90, 'Hasil kerja Anansa sudah baik', '2025-02-10 21:04:40', '2026-07-06 21:22:34'),
(3014, 67, 40, '', '141b0252f4a37fa017c041ce17a8e719.pdf', NULL, 90, 'Hasil kerja Anansa sudah baik, namun sumber rujukan kurang relevan', '2025-02-10 21:04:40', '2026-07-06 21:22:34'),
(3015, 46, 22, 'Benar, alat itu bisa mendeteksi borak. Alat itu menggunakan sensor warna yang bisa mendeteksi perubahan warna pada makanan yang mengandung borak.', NULL, NULL, NULL, NULL, '2025-02-11 07:02:13', NULL),
(3016, 47, 22, 'Alat itu punya sensor warna dan LED yang bisa mendeteksi perubahan warna makanan karena borak.', NULL, NULL, NULL, NULL, '2025-02-11 07:02:13', NULL),
(3017, 48, 22, 'Kepekaan Sensor: Sensor yang digunakan dalam alat harus sensitif terhadap borak dengan batas deteksi yang rendah.\r\n\r\nKetelitian Pengukuran: Alat harus mampu memberikan hasil pengukuran yang akurat dan presisi untuk memastikan keandalan deteksi.\r\n\r\nKecepatan Respon: Alat harus dapat mendeteksi borak dengan cepat untuk efisiensi waktu.\r\n\r\nKestabilan Sistem: Alat harus stabil dan terhindar dari kesalahan yang dapat mengganggu hasil deteksi.', NULL, NULL, NULL, NULL, '2025-02-11 07:02:13', NULL),
(3018, 49, 22, 'Biaya pembuatan alat ini sekitar Rp 50.000,- karena kita perlu beli sensor, LED, dan komponen lainnya.', NULL, NULL, NULL, NULL, '2025-02-11 07:02:13', NULL),
(3019, 50, 22, 'Hipotesisnya gini: \"Semakin tinggi konsentrasi borak dalam makanan, maka semakin pekat warna makanan tersebut. \" Kita bisa mengetes hipotesis ini dengan berbagai jenis makanan dan mengukur perubahan warnanya setelah ditambahkan borak.', NULL, NULL, NULL, NULL, '2025-02-11 07:02:13', NULL),
(3020, 38, 35, 'Boraks sering digunakan secara ilegal oleh sebagian produsen atau pedagang karena dapat membuat makanan menjadi lebih kenyal, tahan lama, memiliki tekstur lebih menarik, dan tidak mudah rusak.', NULL, NULL, 85, 'Hasil kerja bisa lebih dengan melakukan identifikasi masalah', '2025-02-11 07:57:48', '2026-07-28 00:09:12'),
(3021, 39, 35, 'karena adanya oknum yang menyalahgunakan boraks yang seharusnya tidak di gunakan untuk mengawetkan makanan dan kurangnya penegtahuan masyarakat akan bahayabya boraks', NULL, NULL, 90, 'Hasil Kerja sudah baik', '2025-02-11 07:57:48', '2026-07-28 00:09:12'),
(3022, 40, 35, 'Mengkonsumsi makanan yang mengandung boraks memang tidak serta berakibat buruk secara langsung, tetapi boraks akan menumpuk sedikit demi sedikit karena diserap dalam tubuh. Seringnya mengkonsumsi makanan yang mengandung boraks akan menyebabkan gangguan otak, hati, dan ginjal.', NULL, NULL, 85, 'Hasil Kerja sudah baik', '2025-02-11 07:57:48', '2026-07-28 00:09:12'),
(3023, 41, 35, '', 'd35ccbb57cdf542cdcecc624202ed1ac.pdf', NULL, 90, 'Hasil Kerja sudah baik', '2025-02-11 07:57:48', '2026-07-28 00:09:12'),
(3024, 42, 35, 'Sebelum melakukan kunjungan lapangan, kelompok kami menyusun rencana pengamatan untuk memperoleh informasi mengenai kondisi permasalahan penggunaan boraks pada makanan serta kebutuhan masyarakat terhadap teknologi deteksi bahan berbahaya. Pengamatan dilakukan secara sistematis dengan memperhatikan beberapa aspek, metode pengumpulan data, dan instrumen yang digunakan.\r\nAspek yang diamati meliputi kondisi lingkungan atau tempat produksi/penjualan makanan, jenis makanan yang berpotensi mengandung bahan tambahan berbahaya, cara pengolahan dan penyimpanan makanan, pengetahuan masyarakat atau pedagang mengenai penggunaan boraks, serta kebutuhan terhadap alat pendeteksi boraks yang mudah digunakan. Selain itu, diamati juga kendala yang dihadapi masyarakat dalam mengenali makanan yang mengandung boraks.\r\nMetode pengumpulan data dilakukan melalui observasi langsung, wawancara, dan dokumentasi. Observasi dilakukan dengan mengamati kondisi tempat, proses pengolahan atau penjualan makanan, serta karakteristik produk pangan yang tersedia. Wawancara dilakukan kepada pedagang, produsen makanan, atau masyarakat untuk memperoleh informasi mengenai pemahaman mereka terhadap bahaya boraks dan cara mendeteksi keberadaannya. Dokumentasi dilakukan dengan mengambil foto, video, dan mencatat hasil temuan selama kegiatan lapangan.\r\nInstrumen yang digunakan dalam pengamatan berupa lembar observasi, pedoman wawancara, alat dokumentasi (kamera/telepon genggam), alat tulis, serta catatan lapangan. Lembar observasi digunakan untuk mencatat hasil pengamatan secara terstruktur, sedangkan pedoman wawancara digunakan untuk memperoleh informasi yang lebih mendalam terkait penggunaan bahan tambahan pangan dan kebutuhan teknologi deteksi.', NULL, NULL, 95, 'Hasil Kerja sudah baik', '2025-02-11 08:01:48', '2026-07-28 00:09:12'),
(3025, 43, 35, '', 'a3c5fdf744d4e7278caa8c2518ab6cbd.docx', NULL, 85, '', '2025-02-11 08:01:48', '2026-07-28 00:09:12'),
(3027, 45, 35, 'A. Pembuka (untuk membangun suasana)\r\n1.	Boleh tahu Ibu/Bapak sudah berjualan makanan ini sejak kapan?\r\n2.	Apa yang biasanya menjadi perhatian utama Ibu/Bapak dalam menjaga kualitas dagangan?\r\nB. Pengetahuan Umum tentang Boraks dan Keamanan Pangan\r\n1.	Apakah Ibu/Bapak pernah mendengar tentang boraks?\r\n2.	Dari mana biasanya Ibu/Bapak mendapatkan informasi tentang bahan tambahan makanan (misalnya dari penyuluhan, TV, media sosial, dll)?\r\n3.	Menurut Ibu/Bapak, apa dampak atau bahaya jika makanan mengandung boraks? ', NULL, NULL, 85, 'Hasil Kerja sudah baik', '2025-02-11 08:01:48', '2026-07-28 00:09:12'),
(3028, 81, 35, 'Berdasarkan hasil observasi, wawancara, dan pengujian yang telah dilakukan, ditemukan bahwa aspek keamanan makanan masih menjadi perhatian penting karena terdapat potensi penggunaan bahan tambahan pangan yang tidak sesuai dengan ketentuan, salah satunya adalah boraks. Beberapa makanan tertentu memiliki karakteristik fisik seperti tekstur lebih kenyal, lebih tahan lama, dan tampilan yang lebih menarik yang dapat menjadi indikasi adanya penggunaan bahan tambahan berbahaya. Namun, karakteristik tersebut tidak dapat dijadikan satu-satunya dasar untuk memastikan kandungan boraks sehingga diperlukan metode deteksi yang lebih akurat.\r\nHasil wawancara menunjukkan bahwa sebagian masyarakat dan pedagang masih memiliki keterbatasan pengetahuan mengenai bahaya penggunaan boraks pada makanan. Beberapa pelaku usaha mungkin menggunakan bahan tambahan tertentu karena dianggap dapat meningkatkan kualitas produk dan memperpanjang masa simpan, tanpa memahami dampak kesehatan yang dapat ditimbulkan. Kondisi ini menunjukkan pentingnya edukasi mengenai keamanan pangan dan penggunaan bahan tambahan yang aman.', NULL, NULL, 90, '', '2025-02-11 08:01:48', '2026-07-28 00:09:12'),
(3029, 82, 35, 'Berdasarkan temuan hasil observasi, wawancara, dan pengujian, diperlukan inovasi teknologi yang dapat membantu masyarakat maupun petugas keamanan pangan dalam mendeteksi makanan yang berpotensi mengandung boraks secara cepat, akurat, dan mudah digunakan. Beberapa alternatif solusi yang dapat dikembangkan antara lain:\r\n\r\nAlat deteksi boraks berbasis sensor warna digital\r\nMengembangkan alat portabel yang menggunakan sensor warna seperti TCS34725 untuk membaca perubahan warna pada sampel makanan setelah diberikan larutan indikator tertentu. Data hasil pembacaan sensor kemudian diolah oleh mikrokontroler seperti ESP32 untuk memberikan informasi mengenai indikasi keberadaan boraks. Teknologi ini memiliki keunggulan karena ukurannya sederhana, mudah dibawa, dan dapat digunakan untuk pemeriksaan langsung di lapangan.\r\nKit uji cepat (rapid test kit) boraks yang praktis\r\nMengembangkan perangkat uji berbentuk kit sederhana dengan bahan indikator yang dapat menunjukkan perubahan warna apabila sampel makanan mengandung boraks. Solusi ini dapat digunakan oleh masyarakat umum karena prosedurnya sederhana dan tidak membutuhkan perangkat elektronik yang kompleks.', NULL, NULL, 85, '', '2025-02-11 08:01:48', '2026-07-28 00:09:12'),
(3030, 72, 35, '', '46c7f5ea5bcd8946cea27aab3ec59361.pdf', NULL, 80, 'Dokumentasi yang ananda sajikan belum menunnjukan bukti kuat kegiatan observasi', '2025-02-11 08:01:48', '2026-07-28 00:09:12'),
(3031, 46, 35, 'Alat deteksi boraks portabel bekerja dengan memanfaatkan kertas indikator yang mengandung kurkumin dari ekstrak kunyit sebagai sensor pendeteksi. Ketika sampel makanan yang telah diteteskan pada media indikator mengandung boraks, akan terjadi reaksi kimia antara boraks dan kurkumin yang menghasilkan perubahan warna dari kuning menjadi merah kecokelatan atau jingga kemerahan. Sebaliknya, jika sampel tidak mengandung boraks, warna indikator tetap kuning. Perubahan warna tersebut menjadi indikator visual yang memudahkan pengguna mengetahui ada atau tidaknya kandungan boraks pada makanan. Dengan desain yang ringkas dan mudah dibawa, alat ini dapat digunakan secara cepat, praktis, dan ekonomis sebagai deteksi awal (screening test) tanpa memerlukan peralatan laboratorium atau tenaga ahli. Meskipun hasilnya bersifat kualitatif dan tidak menunjukkan kadar boraks secara pasti, alat ini efektif untuk membantu masyarakat melakukan pemeriksaan awal terhadap keamanan pangan sebelum dilakukan pengujian lebih lanjut di laboratorium jika diperlukan.', NULL, NULL, 95, '', '2025-02-11 08:04:09', '2026-07-28 00:09:12'),
(3032, 47, 35, 'Cara kerja alat deteksi boraks portabel dapat dijelaskan melalui keterpaduan konsep fisika, kimia, dan biologi. Dari aspek kimia, alat ini memanfaatkan reaksi antara senyawa kurkumin pada indikator kunyit dengan boraks yang menghasilkan perubahan warna dari kuning menjadi merah kecokelatan. Perubahan warna tersebut terjadi karena terbentuknya kompleks antara kurkumin dan ion borat, sehingga menjadi indikator adanya kandungan boraks pada sampel makanan. Dari aspek fisika, proses penyerapan larutan sampel ke dalam kertas indikator terjadi melalui gaya kapilaritas, sedangkan perubahan warna dapat diamati karena cahaya yang dipantulkan oleh permukaan indikator mengalami perubahan sesuai sifat optik zat hasil reaksi. Dari aspek biologi, boraks bukan merupakan bahan tambahan pangan yang aman karena dapat terakumulasi di dalam tubuh dan menyebabkan gangguan kesehatan, seperti iritasi saluran pencernaan, kerusakan hati dan ginjal, serta gangguan sistem saraf apabila dikonsumsi secara terus-menerus dalam jumlah berlebih. Oleh karena itu, penggunaan alat deteksi boraks portabel berperan dalam mendukung keamanan pangan dengan membantu masyarakat mendeteksi secara dini keberadaan boraks pada makanan sehingga dapat mengurangi risiko konsumsi pangan yang berbahaya bagi kesehatan.', NULL, NULL, 90, '', '2025-02-11 08:04:09', '2026-07-28 00:09:12'),
(3033, 48, 35, 'Berdasarkan pertimbangan efektivitas, akurasi yang memadai untuk deteksi awal, kemudahan penggunaan, biaya, dan kepraktisan, dipilih solusi berupa alat deteksi boraks portabel yang mengadopsi prinsip kerja kertas indikator kunyit sebagai sensor utama. Alat ini dirancang dalam bentuk yang ringkas, mudah dibawa, dan sederhana digunakan, sehingga pengguna hanya perlu meneteskan ekstrak sampel makanan pada media indikator untuk mengamati perubahan warna sebagai tanda adanya boraks. Dengan memadukan media indikator ke dalam perangkat portabel, solusi yang dikembangkan tidak hanya mampu mendeteksi boraks secara cepat sebagai screening test, tetapi juga lebih praktis digunakan oleh masyarakat, siswa, maupun petugas di lapangan tanpa memerlukan fasilitas laboratorium.', NULL, NULL, 95, '', '2025-02-11 08:04:09', '2026-07-28 00:09:12'),
(3034, 49, 35, 'Berdasarkan hasil perbandingan terhadap beberapa alternatif solusi, yaitu penggunaan larutan kunyit, kertas indikator kunyit, test kit boraks komersial, dan analisis laboratorium, diperoleh bahwa masing-masing alternatif memiliki kelebihan dan keterbatasan. Analisis laboratorium memberikan tingkat akurasi yang sangat tinggi, tetapi memerlukan peralatan khusus, biaya yang relatif besar, serta tidak praktis untuk digunakan di lapangan. Test kit komersial lebih mudah digunakan, namun masih bergantung pada ketersediaan produk dan memiliki biaya yang relatif lebih tinggi. Sementara itu, larutan kunyit dan kertas indikator kunyit menawarkan biaya yang lebih murah, mudah diperoleh, serta memanfaatkan reaksi perubahan warna kurkumin terhadap boraks. Berdasarkan pertimbangan efektivitas, akurasi yang memadai untuk deteksi awal, kemudahan penggunaan, biaya, dan kepraktisan, dipilih solusi berupa alat deteksi boraks portabel yang mengadopsi prinsip kerja kertas indikator kunyit sebagai sensor utama. Alat ini dirancang dalam bentuk yang ringkas, mudah dibawa, dan sederhana digunakan, sehingga pengguna hanya perlu meneteskan ekstrak sampel makanan pada media indikator untuk mengamati perubahan warna sebagai tanda adanya boraks. Dengan memadukan media indikator ke dalam perangkat portabel, solusi yang dikembangkan tidak hanya mampu mendeteksi boraks secara cepat sebagai screening test, tetapi juga lebih praktis digunakan oleh masyarakat, siswa, maupun petugas di lapangan tanpa memerlukan fasilitas laboratorium.', NULL, NULL, 95, 'Hasil Kerja Sudah baik', '2025-02-11 08:04:09', '2026-07-28 00:09:12'),
(3035, 50, 35, 'Efektivitas alat deteksi boraks portabel dipengaruhi oleh beberapa faktor. Pertama, konsentrasi boraks dalam sampel makanan, karena semakin tinggi konsentrasi boraks maka perubahan warna pada indikator akan semakin jelas. Kedua, kualitas indikator kurkumin, yang dipengaruhi oleh konsentrasi ekstrak kunyit, ketebalan kertas indikator, serta cara penyimpanannya sehingga tetap sensitif terhadap boraks. Ketiga, kondisi sampel makanan, seperti warna, kadar air, pH, atau kandungan zat lain yang dapat memengaruhi kejelasan hasil deteksi. Keempat, prosedur penggunaan alat, seperti jumlah sampel yang diteteskan, lama waktu kontak antara sampel dan indikator, serta ketelitian pengguna dalam mengamati perubahan warna. Selain itu, kondisi lingkungan, seperti pencahayaan saat pengamatan dan suhu penyimpanan alat, juga dapat memengaruhi hasil deteksi.\r\nBerdasarkan analisis tersebut, hipotesis penyelidikan kelompok dirumuskan sebagai berikut: \"Jika alat deteksi boraks portabel menggunakan indikator berbasis kurkumin dengan prosedur penggunaan yang tepat, maka alat tersebut akan mampu mendeteksi keberadaan boraks pada makanan melalui perubahan warna yang jelas, cepat, dan mudah diamati. Semakin tinggi konsentrasi boraks dalam sampel, semakin nyata perubahan warna yang dihasilkan sehingga efektivitas deteksi akan meningkat.\"', NULL, NULL, 95, '', '2025-02-11 08:04:09', '2026-07-28 00:09:12'),
(3036, 52, 30, 'port sebagai power untuk mengaktifkan alat pendeteksi boraks\r\nsensor warna TCS 3200 untuk mendeteksi adanya kandungan boraks \r\njumper berfungsi untuk menghubungkan komponen satu dengan komponen lainnya\r\nbluetooth HC 05 berfungsi sebagai komponen yang terhubung dengan smartphone \r\nardiuno uno berfungsi untuk mengendalikan alat dan memudahkan dalam memprogram', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(3037, 53, 30, 'Kelompok kami mengembangkan alat deteksi boraks portabel yang dilengkapi dengan sensor warna untuk mendeteksi perubahan warna reagen secara otomatis. Hasil deteksi ditampilkan secara real-time pada layar dan dapat dihubungkan ke smartphone melalui Bluetooth, sehingga pengguna dapat mengetahui hasil pengujian dengan lebih cepat dan mudah. Alat ini juga dirancang dalam ukuran yang ringkas, menggunakan baterai isi ulang, serta dilengkapi casing yang dibuat dari bahan yang mudah ditemukan. Keunggulan inovasi ini dibandingkan alat yang sudah ada adalah proses pembacaan hasil menjadi lebih objektif karena tidak bergantung pada pengamatan visual pengguna. Selain itu, alat memiliki waktu deteksi yang lebih cepat, mudah dioperasikan oleh masyarakat, dan dapat digunakan sebagai skrining awal keamanan makanan secara praktis. Penggunaan casing dari bahan yang mudah diperoleh juga membuat biaya produksi lebih terjangkau, memudahkan proses perakitan dan perawatan, serta memungkinkan alat direplikasi untuk keperluan pendidikan maupun penggunaan di lapangan. Dengan desain yang portabel, ekonomis, dan mudah digunakan.', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(3038, 83, 30, 'Sensor Warna TCS3200 = 20.000\r\nJumper = 15000\r\nModul Bluetooth HC-05 = 30000\r\nArduino Uno = 60000', NULL, NULL, 90, 'Hasil kerja ananda yang sudah baik', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(3039, 51, 30, '', NULL, 'b2cfb13d5548cdefb7583818db386592.jpg', 90, 'Hasil kerja yang sudah baik, Ananda sudah berusaha dengan keras', '2025-02-11 13:58:30', '2026-07-06 21:22:34'),
(3040, 54, 35, 'Kelompok kami memilih desain prototipe alat deteksi boraks berbasis sensor warna portabel karena alat ini dirancang untuk menjawab permasalahan keamanan pangan, khususnya kesulitan masyarakat dalam mendeteksi kandungan boraks pada makanan secara cepat dan praktis. Desain ini dipilih karena menggabungkan teknologi sensor, mikrokontroler, dan sistem tampilan digital sehingga proses identifikasi dapat dilakukan dengan lebih mudah dibandingkan metode pemeriksaan konvensional yang membutuhkan waktu lebih lama dan fasilitas laboratorium.\r\nPrototipe ini menggunakan sensor warna TCS34725 yang mampu membaca perubahan karakteristik warna pada sampel makanan setelah diberikan larutan indikator tertentu. Data hasil pembacaan sensor kemudian diproses oleh mikrokontroler ESP32 untuk menghasilkan informasi deteksi yang ditampilkan melalui layar. Penggunaan sistem elektronik dalam alat ini memungkinkan proses pengukuran dilakukan secara lebih konsisten karena pembacaan warna tidak hanya bergantung pada pengamatan visual manusia.', NULL, NULL, 90, '', '2025-02-11 08:09:08', '2026-07-28 00:09:12'),
(3041, 55, 35, 'Tujuan pembuatan prototipe alat deteksi boraks sensor portabel adalah untuk mengembangkan alat bantu deteksi keamanan pangan yang mampu mengidentifikasi indikasi keberadaan boraks pada makanan secara cepat, praktis, dan mudah digunakan. Prototipe ini dirancang sebagai solusi terhadap permasalahan keterbatasan masyarakat dalam mengenali makanan yang mengandung bahan tambahan pangan berbahaya melalui pengamatan sederhana.', NULL, NULL, 90, 'Hasil kerja Ananda sudah baik', '2025-02-11 08:09:08', '2026-07-28 00:09:12'),
(3042, 56, 35, 'Alat\r\nSolder dan timah solder (untuk merangkai komponen elektronik)\r\nTang potong dan tang penjepit\r\nObeng kecil\r\nCutter/gunting\r\nMultimeter (untuk mengecek rangkaian listrik)\r\nLaptop/komputer untuk pemrograman mikrokontroler\r\nKabel USB untuk menghubungkan mikrokontroler dengan komputer\r\nLem tembak atau perekat untuk pemasangan komponen\r\nBor kecil (jika diperlukan untuk membuat lubang pada casing)\r\nAlat ukur sederhana (penggaris/meteran)\r\nBahan Komponen Elektronik\r\nMikrokontroler ESP32 DevKit sebagai pusat pengolahan data sensor\r\nSensor warna TCS34725 untuk membaca perubahan warna sampel makanan\r\nLayar LCD/OLED sebagai media tampilan hasil deteksi\r\nModul baterai atau baterai isi ulang sebagai sumber daya portabel\r\nSaklar ON/OFF\r\nKabel jumper (male-male, male-female, female-female)\r\nBreadboard atau PCB untuk merangkai komponen\r\nResistor sesuai kebutuhan rangkaian\r\nModul pengisian baterai (misalnya TP4056) jika menggunakan baterai lithium\r\nKabel penghubung antar komponen\r\nBahan Pendukung Alat\r\nCasing pelindung (akrilik, plastik, atau hasil cetak 3D) untuk melindungi rangkaian elektronik\r\nWadah sampel makanan\r\nLarutan indikator pendeteksi boraks\r\nSampel makanan yang akan diuji (misalnya bakso, mi, kerupuk, atau makanan olahan lainnya)\r\nLabel atau penanda komponen alat', NULL, NULL, 95, '', '2025-02-11 08:09:08', '2026-07-28 00:09:12'),
(3043, 57, 35, 'Sebelum pembuatan prototipe dilakukan, kelompok kami menyusun langkah-langkah pembuatan agar proses perakitan alat dapat berjalan secara sistematis sesuai dengan desain yang telah dibuat. Tahapan pembuatan prototipe alat deteksi boraks sensor portabel adalah sebagai berikut:\r\n\r\nMenyiapkan alat dan bahan\r\nMenyiapkan seluruh komponen yang diperlukan, seperti ESP32 DevKit, sensor warna TCS34725, LCD/OLED, baterai, kabel jumper, breadboard/PCB, casing alat, serta bahan pendukung berupa sampel makanan dan larutan indikator pendeteksi boraks.\r\nMembuat rancangan rangkaian elektronik\r\nMenyusun desain hubungan antar komponen elektronik, meliputi koneksi sensor TCS34725 dengan mikrokontroler ESP32, pemasangan layar indikator, serta sistem sumber daya agar alat dapat bekerja sesuai rancangan.\r\nMerakit komponen elektronik\r\nMenghubungkan seluruh komponen elektronik sesuai skema rangkaian. Sensor warna dipasang sebagai komponen utama untuk membaca perubahan warna sampel, sedangkan ESP32 digunakan untuk mengolah data hasil pembacaan sensor.\r\nMelakukan pemrograman mikrokontroler ESP32\r\nMembuat dan mengunggah program pada ESP32 agar mampu menerima data dari sensor, mengolah informasi hasil pembacaan warna, dan menampilkan hasil deteksi pada layar.\r\nMembuat dan memasang casing prototipe\r\nMendesain serta membuat casing untuk melindungi komponen elektronik. Penempatan sensor, ruang sampel, layar, dan tombol pengoperasian disesuaikan agar alat lebih rapi, aman, dan mudah digunakan.\r\nMengintegrasikan seluruh komponen alat\r\nMemasang rangkaian elektronik ke dalam casing dan memastikan setiap bagian, seperti sensor, mikrokontroler, sumber daya, dan layar, terhubung dengan baik.\r\nMelakukan pengujian awal prototipe\r\nMenguji fungsi dasar alat dengan memasukkan sampel makanan dan mengamati apakah sensor mampu membaca perubahan warna serta apakah sistem dapat menampilkan hasil deteksi.', NULL, NULL, 90, '', '2025-02-11 08:09:08', '2026-07-28 00:09:12'),
(3044, 58, 35, 'Sebelum melakukan pengujian, kelompok kami menyusun langkah-langkah pengujian untuk mengetahui kinerja prototipe alat deteksi boraks sensor portabel berdasarkan indikator keberhasilan yang telah ditetapkan. Tahapan pengujian dilakukan secara sistematis sebagai berikut:\r\n\r\nMenyiapkan alat dan bahan pengujian\r\nMenyiapkan prototipe alat deteksi boraks yang telah dibuat, sampel makanan yang akan diuji, larutan indikator pendeteksi boraks, sumber daya alat, serta alat pendukung dokumentasi dan pencatatan data.\r\nMemeriksa kondisi prototipe\r\nMemastikan seluruh komponen alat telah terpasang dengan baik, meliputi sensor warna TCS34725, mikrokontroler ESP32, layar indikator, baterai, dan rangkaian elektronik. Pemeriksaan dilakukan untuk memastikan alat dapat menyala dan berfungsi dengan baik.\r\nMelakukan kalibrasi awal alat\r\nMelakukan pengecekan dan pengaturan awal sensor agar pembacaan warna dapat dilakukan secara optimal. Tahap ini bertujuan untuk memastikan sensor mampu membaca perubahan warna sampel secara konsisten.\r\nMenyiapkan sampel makanan untuk pengujian\r\nMenyiapkan beberapa sampel makanan yang akan diuji, kemudian memberikan perlakuan sesuai prosedur deteksi, yaitu mencampurkan sampel dengan larutan indikator pendeteksi boraks.\r\nMelakukan proses deteksi menggunakan prototipe\r\nMemasukkan sampel yang telah diberi perlakuan ke dalam ruang sampel alat, kemudian mengaktifkan sistem agar sensor TCS34725 membaca perubahan warna yang terjadi.\r\nMengamati dan mencatat hasil pembacaan sensor\r\nMengamati data hasil pembacaan sensor yang diproses oleh ESP32 dan ditampilkan pada layar. Data yang diperoleh dicatat untuk mengetahui kemampuan alat dalam mendeteksi indikasi keberadaan boraks.\r\nMengevaluasi kinerja prototipe berdasarkan indikator keberhasilan\r\nMelakukan evaluasi terhadap beberapa aspek, seperti kestabilan pembacaan sensor, keakuratan hasil deteksi, kemudahan penggunaan, kepraktisan alat, dan keamanan desain.', NULL, NULL, 90, '', '2025-02-11 08:15:14', '2026-07-28 00:09:12'),
(3045, 60, 35, 'Perlu perbaikan pada tahap berikutnya difokuskan pada penyempurnaan desain casing, pengaturan ruang sampel agar lebih tertutup, stabilisasi posisi sensor, perapian rangkaian elektronik, serta peningkatan kemudahan penggunaan. Perbaikan ini diharapkan dapat meningkatkan kestabilan, akurasi, dan kepraktisan prototipe pada Uji Coba 2.', NULL, NULL, 90, '', '2025-02-11 08:15:14', '2026-07-28 00:09:12'),
(3046, 61, 35, '| **Indikator Pengujian**                   | **Hasil Uji Coba 2**                                                                                                                                                                          |\r\n| ----------------------------------------- | --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\r\n| **Fungsi utama alat**                     | Prototipe mampu menjalankan fungsi deteksi dengan baik melalui proses pembacaan perubahan warna sampel menggunakan sensor TCS34725 dan pengolahan data menggunakan mikrokontroler ESP32.      |\r\n| **Kestabilan pembacaan sensor**           | Hasil pembacaan sensor lebih stabil setelah dilakukan perbaikan ruang sampel dan posisi sensor. Gangguan cahaya dari lingkungan dapat dikurangi sehingga data yang diperoleh lebih konsisten. |\r\n| **Keakuratan hasil deteksi**              | Hasil deteksi menunjukkan peningkatan dibandingkan Uji Coba 1 karena sistem pembacaan warna lebih terkontrol dan komponen bekerja lebih optimal.                                              |\r\n| **Kepraktisan penggunaan**                | Desain casing yang telah diperbaiki membuat alat lebih mudah dibawa, lebih nyaman digunakan, dan komponen lebih terlindungi selama proses pengujian.                                          |\r\n| **Kinerja sistem elektronik**             | Rangkaian ESP32, sensor TCS34725, dan layar indikator dapat bekerja dengan lebih baik karena koneksi antar komponen telah diperbaiki dan dirapikan.                                           |\r\n| **Kemudahan interpretasi hasil**          | Tampilan hasil deteksi lebih mudah dipahami oleh pengguna karena informasi yang diberikan lebih jelas dibandingkan prototipe awal.                                                            |\r\n| **Kesesuaian dengan tujuan pengembangan** | Prototipe mampu menunjukkan potensi sebagai alat bantu deteksi awal makanan yang diduga mengandung boraks secara cepat, praktis, dan dapat digunakan di lapangan.                             |\r\n', NULL, NULL, 85, '', '2025-02-11 08:15:14', '2026-07-28 00:09:12'),
(3047, 64, 35, 'prototipe akhir alat deteksi boraks sensor portabel dinyatakan efektif dan telah memenuhi indikator keberhasilan yang ditetapkan. Prototipe ini berpotensi menjadi solusi teknologi sederhana, praktis, dan mudah digunakan untuk membantu proses pemeriksaan awal keamanan pangan, khususnya dalam mendeteksi kemungkinan keberadaan boraks pada makanan.', NULL, NULL, 85, '', '2025-02-11 08:15:14', '2026-07-28 00:09:12'),
(3048, 84, 35, 'Hasil Uji Coba 1 menunjukkan bahwa prototipe telah mampu menjalankan fungsi dasar deteksi, yaitu membaca perubahan warna pada sampel makanan menggunakan sensor warna TCS34725 dan mengolah data melalui mikrokontroler ESP32. Namun, masih ditemukan beberapa keterbatasan, seperti hasil pembacaan sensor yang belum sepenuhnya konsisten karena pengaruh kondisi pencahayaan lingkungan. Selain itu, desain casing masih perlu diperbaiki karena belum optimal dalam melindungi komponen elektronik dan belum memberikan kenyamanan maksimal saat alat digunakan.', NULL, NULL, 85, 'Belum disesuaikan dengan indikator keberhaislan yang telah ditetapkan', '2025-02-11 08:15:14', '2026-07-28 00:09:12'),
(3049, 59, 35, '', 'f4780f1f4d108402f97d24d4e0023c2b.docx', NULL, 90, '', '2025-02-11 08:15:14', '2026-07-28 00:09:12'),
(3050, 63, 35, '', '7207cce1602c073184409d203d181743.docx', NULL, 90, '', '2025-02-11 08:15:14', '2026-07-28 00:09:12'),
(3051, 62, 35, 'Berdasarkan indikator keberhasilan yang telah ditetapkan, kelompok kami menetapkan beberapa target sebagai acuan dalam pengujian prototipe. Pertama, akurasi deteksi, yaitu alat mampu menunjukkan perubahan warna yang jelas pada sampel yang mengandung boraks dan tidak menunjukkan perubahan warna pada sampel yang tidak mengandung boraks. Kedua, kecepatan deteksi, yaitu hasil dapat diamati dalam waktu maksimal 3 menit setelah sampel diteteskan pada strip indikator. Ketiga, kemudahan penggunaan, yaitu alat dapat digunakan dengan langkah-langkah yang sederhana dan mudah dipahami tanpa memerlukan pelatihan khusus. Keempat, kepraktisan alat, yaitu seluruh komponen terintegrasi dalam satu casing portabel sehingga mudah dibawa, disimpan, dan digunakan di berbagai lokasi. Kelima, keamanan penggunaan, yaitu bahan yang digunakan aman, tidak mudah rusak, dan meminimalkan risiko kontaminasi selama proses pengujian. Apabila seluruh target tersebut tercapai, maka prototipe dinilai telah memenuhi indikator keberhasilan sebagai alat deteksi awal (screening test) boraks pada makanan dan layak untuk dikembangkan lebih lanjut melalui tahap penyempurnaan (redesign).', NULL, 'e1f1d3f4070e8c635ead3062d327acf4.jpg', 90, '', '2025-02-11 08:15:14', '2026-07-28 00:09:12'),
(3052, 65, 35, 'Penurunan kinerja prototipe alat deteksi boraks setelah digunakan berulang kali dapat disebabkan oleh beberapa faktor yang berkaitan dengan prinsip kerja sensor dan komponen alat. Sensor warna TCS34725 bekerja dengan membaca perubahan intensitas warna pada sampel, sehingga adanya kotoran pada sensor atau ruang sampel, perubahan posisi sensor, dan gangguan cahaya lingkungan dapat menyebabkan hasil pembacaan kurang akurat.\r\nSelain itu, penggunaan berulang dapat menyebabkan koneksi kabel menjadi kurang stabil, daya baterai menurun, atau terjadi gangguan pada rangkaian elektronik sehingga proses pengolahan data oleh ESP32 tidak optimal. Casing yang kurang kuat juga dapat menyebabkan posisi komponen berubah dan memengaruhi kestabilan pengukuran. Oleh karena itu, diperlukan perawatan rutin, pembersihan sensor, pengecekan rangkaian, dan kalibrasi ulang agar kinerja alat tetap stabil dan hasil deteksi lebih akurat.\r\n', NULL, NULL, 90, '', '2025-02-11 08:16:54', '2026-07-28 00:09:12'),
(3053, 89, 35, 'solusi inovatif yang berpotensi meningkatkan keamanan pangan. Melalui integrasi teknologi IoT, alat ini mampu menyajikan informasi secara real-time dan portabel melalui layar LCD dan perangkat\r\n', NULL, NULL, 80, '', '2025-02-11 08:16:54', '2026-07-28 00:09:12'),
(3054, 67, 35, '', 'ef70eba3305aea8474b053beceb93e73.pdf', NULL, 95, 'Referensi sangat baik', '2025-02-11 08:16:54', '2026-07-28 00:09:12'),
(3055, 70, 35, 'Setelah melaksanakan proyek perancangan dan pembuatan teknologi deteksi boraks pada makanan, kelompok kami memperoleh pengetahuan, keterampilan, dan pengalaman baru dalam mengembangkan solusi berbasis teknologi untuk menyelesaikan permasalahan keamanan pangan. Dari aspek pengetahuan, proyek ini meningkatkan pemahaman kami tentang konsep IPA, khususnya sifat bahan kimia, perubahan warna akibat reaksi indikator, serta prinsip kerja sensor dalam mendeteksi karakteristik suatu bahan. Kami juga memahami bahwa konsep IPA dapat diterapkan untuk menghasilkan teknologi yang bermanfaat bagi masyarakat.\r\nDari aspek teknologi dan rekayasa, proyek ini memberikan pengalaman dalam merancang, membuat, dan menguji prototipe alat deteksi berbasis sensor warna TCS34725 dan mikrokontroler ESP32. Kami belajar bahwa proses pembuatan teknologi tidak hanya berfokus pada menghasilkan alat yang berfungsi, tetapi juga memerlukan proses perancangan, pengujian, evaluasi, dan perbaikan desain agar alat menjadi lebih efektif dan mudah digunakan. Kegiatan redesign setelah uji coba juga memberikan pengalaman dalam menerapkan prinsip engineering design process untuk mengatasi permasalahan yang ditemukan selama pengujian.\r\n\r\n', NULL, NULL, 90, 'Aspek Matematika masih belum di sajikan', '2025-02-11 08:18:53', '2026-07-28 00:09:12'),
(3056, 85, 35, 'kendala yang muncul disebabkan oleh faktor teknis, keterbatasan komponen, kondisi lingkungan pengujian, serta proses adaptasi dalam mengintegrasikan konsep IPA, teknologi, rekayasa, dan matematika selain itu kami juga masih kesulitan menemukan referensi yang sesuai\r\n\r\n', NULL, NULL, 90, '', '2025-02-11 08:18:53', '2026-07-28 00:09:12'),
(3057, 86, 35, 'Saling nyari artikel dan referensi seluruh anggota kelompok dan mencari bacaan untuk menambah penegtahuan', NULL, NULL, 85, '', '2025-02-11 08:18:53', '2026-07-28 00:09:12'),
(3058, 87, 35, '', '1e7ef901429a1fa74ceaf9da9d1e89f9.pdf', NULL, 80, 'Poster masih memiliki kekurangan terkait penyajian info', '2025-02-11 08:18:53', '2026-07-28 00:09:12');
INSERT INTO `tb_jawaban_essai` (`id_jawaban_essai`, `id_soal`, `id_user`, `jawaban_text`, `jawaban_file`, `jawaban_gambar`, `nilai`, `feedback`, `created_at`, `updated_at`) VALUES
(3065, 42, 21, '1. menentukan tujuan penelitian:\r\nMengidentifikasi dan memahami potensi bahaya penggunaan boraks pada makanan yang dijual di pasar.\r\nMeningkatkan kesadaran masyarakat tentang risiko kesehatan terkait konsumsi makanan yang mengandung boraks.\r\n2. Metode penelitian :\r\n- Observasi Visual:\r\nMengamati tekstur, warna, dan aroma makanan untuk mengidentifikasi ciri-ciri yang mencurigakan.\r\nMakanan yang mengandung boraks biasanya memiliki tekstur yang lebih kenyal dan tahan lama.\r\n- Wawancara dengan Pedagang:\r\nMenanyakan kepada pedagang mengenai bahan-bahan yang digunakan dalam pembuatan makanan.\r\nMencari informasi apakah pedagang menggunakan boraks atau bahan pengawet lainnya yang berpotensi berbahaya.\r\n- Pengumpulan Sampel:\r\nMemilih secara acak berbagai jenis makanan yang umum dijual di pasar, seperti bakso dan mie. Mengambil sampel makanan secukupnya untuk pengujian lebih lanjut.\r\n- Pengujian Kandungan Boraks:\r\nMelakukan pengujian kualitatif atau kuantitatif untuk mendeteksi keberadaan boraks dalam sampel makanan. Metode pengujian dapat bervariasi, seperti menggunakan kit pengujian cepat atau metode laboratorium yang lebih akurat.\r\n- Pencatatan dan Analisis Data:\r\nMencatat semua hasil pengujian dan observasi secara rinci. Menganalisis data untuk mengetahui prevalensi penggunaan boraks pada makanan yang dijual di pasar.\r\n\r\n3. Hasil yang Diharapkan:\r\nData mengenai jenis makanan yang paling berisiko mengandung boraks.\r\nInformasi tentang ciri-ciri makanan yang mengandung boraks secara visual.\r\nTingkat kesadaran pedagang dan masyarakat mengenai bahaya boraks dalam makanan.\r\n- Pengujian Kandungan Boraks:\r\nMelakukan pengujian kualitatif atau kuantitatif untuk mendeteksi keberadaan boraks dalam sampel makanan. Metode pengujian dapat bervariasi, seperti menggunakan kit pengujian cepat atau metode laboratorium yang lebih akurat.\r\n- Pencatatan dan Analisis Data:\r\nMencatat semua hasil pengujian dan observasi secara rinci. Menganalisis data untuk mengetahui prevalensi penggunaan boraks pada makanan yang dijual di pasar.\r\n4. Kesimpulan:\r\nObservasi makanan di pasar yang mengandung boraks adalah kegiatan penting untuk melindungi kesehatan masyarakat. Dengan mengidentifikasi dan memahami risiko penggunaan boraks, kita dapat mengambil langkah-langkah pencegahan yang tepat dan meningkatkan keamanan pangan secara keseluruhan.\r\n\r\n', NULL, NULL, NULL, NULL, '2025-02-16 16:38:59', NULL),
(3066, 43, 21, 'pasar tradisional yang beroperasi satu kali dalam seminggu seringkali menjadi tempat di mana makanan olahan dan jajanan tradisional dijual. Beberapa pedagang mungkin menggunakan boraks sebagai bahan tambahan makanan untuk memberikan tekstur yang kenyal, tahan lama, dan menarik pada produk mereka.\r\n1. Deskripsi Makanan yang Berpotensi Mengandung Boraks:\r\n- Cimol: Cimol yang dijual di pasar tradisional mungkin memiliki tekstur yang sangat kenyal dan elastis. Beberapa pedagang mungkin menambahkan boraks agar cimol tidak mudah hancur dan tetap renyah lebih lama.\r\n- Bakso: Bakso yang mengandung boraks biasanya memiliki tekstur yang sangat kenyal dan padat. Warna bakso juga mungkin terlihat lebih cerah dan menarik.\r\n- Mie: Mie yang mengandung boraks cenderung lebih kenyal dan tidak mudah putus. Beberapa pedagang mungkin menggunakan boraks untuk memberikan tekstur yang lebih baik pada mie.\r\n- Jajanan Lainnya: Jajanan tradisional seperti cilok, empek-empek, dan kerupuk juga berpotensi mengandung boraks. Makanan ini mungkin memiliki tekstur yang sangat kenyal, elastis, dan tahan lama\r\n2. Ciri-ciri Makanan yang Mengandung Boraks:\r\n- Tekstur Kenyal dan Elastis: Makanan yang mengandung boraks biasanya memiliki tekstur yang sangat kenyal dan elastis, bahkan lebih kenyal dari makanan sejenis yang tidak menggunakan boraks.\r\n- Warna Cerah dan Tidak Cepat Berubah: Boraks dapat membuat warna makanan menjadi lebih cerah dan menarik. Selain itu, makanan yang mengandung boraks juga tidak cepat berubah warna atau membusuk, sehingga terlihat segar lebih lama.\r\n- Tidak Mudah Hancur: Makanan yang mengandung boraks biasanya lebih tahan lama dan tidak mudah hancur.\r\n\r\n.\r\n', NULL, NULL, NULL, NULL, '2025-02-16 16:38:59', NULL),
(3068, 45, 21, '1. Pertanyaan Pembuka:\r\n- Selamat siang, Bapak/Ibu. Terima kasih sudah bersedia meluangkan waktu untuk wawancara ini. Kami sedang melakukan penelitian tentang keamanan makanan di pasar ini.\r\n- Sudah berapa lama Bapak/Ibu berjualan di pasar ini?\r\n- Jenis makanan apa saja yang Bapak/Ibu jual?\r\n2. Pertanyaan Terkait Penggunaan Boraks:\r\n- Apakah Bapak/Ibu mengetahui tentang boraks?\r\n- Apakah Bapak/Ibu pernah mendengar tentang bahaya boraks bagi kesehatan?\r\n- Apakah Bapak/Ibu menggunakan boraks dalam pembuatan atau pengolahan makanan yang dijual?\r\nJika ya, mengapa Bapak/Ibu menggunakan boraks?\r\nJika tidak, apakah Bapak/Ibu memiliki informasi dari pemasok atau sumber lain mengenai kandungan  bahan tambahan pada makanan yang Bapak/Ibu jual?\r\n- Apakah Bapak/Ibu mengetahui ciri-ciri makanan yang mengandung boraks?\r\n- Bagaimana cara Bapak/Ibu memastikan bahwa makanan yang Bapak/Ibu jual aman untuk dikonsumsi dan tidak mengandung bahan berbahaya seperti boraks?\r\n3. Pertanyaan Terkait Pengetahuan dan Sikap:\r\n- Menurut Bapak/Ibu, seberapa penting keamanan makanan bagi konsumen?\r\n- Apakah Bapak/Ibu bersedia untuk tidak menggunakan boraks jika memang terbukti berbahaya bagi kesehatan?\r\n- Apakah Bapak/Ibu memiliki saran atau masukan terkait upaya peningkatan keamanan makanan di pasar ini?\r\n4. Pertanyaan Penutup:\r\n- Terima kasih atas waktu dan informasinya, Bapak/Ibu. Apakah ada hal lain yang ingin Bapak/Ibu sampaikan terkait topik ini?\r\n', NULL, NULL, NULL, NULL, '2025-02-16 16:38:59', NULL),
(3069, 81, 21, 'Kurangnya pengetahuan masyarakat tentang ciri makanan yang mengandung boraks adalah masalah krusial yang berkontribusi terhadap risiko kesehatan, terutama pada anak-anak. Berikut adalah rincian dan bukti pendukungnya:\r\nMinimnya Edukasi dan Sosialisasi\r\nBukti: Banyak penelitian dan survei menunjukkan bahwa tingkat pemahaman masyarakat mengenai bahaya boraks dan ciri-ciri makanan yang mengandungnya masih rendah.\r\nPenjelasan: Informasi tentang boraks dan dampaknya seringkali tidak sampai kepada masyarakat luas, terutama mereka yang tinggal di daerah dengan akses informasi terbatas. Sosialisasi yang kurang efektif melalui media massa, sekolah, atau komunitas juga menjadi faktor penghambat.\r\n2. Informasi yang Tidak Jelas dan Menyesatkan\r\nBukti: Terkadang, informasi tentang boraks bercampur dengan mitos atau informasi yang tidak akurat, sehingga masyarakat sulit membedakan fakta danHoaks.\r\nPenjelasan: Informasi yang simpang siur dapat menyebabkan kebingungan dan bahkan ketidakpedulian terhadap bahaya boraks. Masyarakat menjadi sulit mengidentifikasi makanan yang berpotensi mengandung boraks karena informasi yang mereka terima tidak valid.\r\n3. Kurangnya Pengawasan dan Labelisasi\r\nBukti: Pengawasan terhadap penggunaan boraks pada makanan di pasar tradisional seringkali lemah. Produk makanan juga tidak memiliki label yang jelas mengenai kandungan bahan tambahan makanan.\r\nPenjelasan: Tanpa pengawasan yang ketat, pedagang nakal mungkin dengan sengaja menambahkan boraks pada makanan mereka tanpa menginformasikan kepada konsumen. Kurangnya labelisasi juga membuat konsumen sulit untuk mengetahui kandungan bahan tambahan makanan yang mereka beli.\r\n4. Faktor Ekonomi dan Kebiasaan\r\nBukti: Makanan dengan boraks seringkali lebih murah dan terlihat menarik, sehingga masyarakat dengan keterbatasan ekonomi cenderung membelinya. Selain itu, kebiasaan mengonsumsi jajanan tradisional tanpa memperhatikan kandungan bahan tambahan juga menjadi faktor risiko.\r\nPenjelasan: Faktor ekonomi dan kebiasaan yang sulit diubah membuat masyarakat tetap berisiko terpapar boraks, meskipun sudah ada informasi tentang bahayanya.\r\n5. Target Utama: Anak-anak\r\nBukti: Jajanan anak-anak seperti cilok, bakso, mie, dan kerupuk seringkali mengandung boraks karena disukai oleh anak-anak dan harganya terjangkau.\r\nPenjelasan: Anak-anak adalah kelompok yang paling rentan terhadap efek negatif boraks karena sistem pencernaan mereka masih dalam tahap perkembangan. Pengawasan orang tua sangat penting dalam memilihkan makanan yang aman untuk anak-anak.\r\n\r\n', NULL, NULL, NULL, NULL, '2025-02-16 16:38:59', NULL),
(3070, 82, 21, 'membuat alat yang dapat mendeteksi boraks untuk masyarakat sehingga dapat terhindar dari pedagang yang menggunakan boraks dalam makanananya serta mengedukasi masyarakat memalui poster atau media lainnya tentang bahaya boraks terutama pada anak-anak.', NULL, NULL, NULL, NULL, '2025-02-16 16:38:59', NULL),
(3071, 72, 21, NULL, 'b8a658feffbe76a443fd74f4b6ec2fca.pdf', NULL, NULL, NULL, '2025-02-16 16:38:59', NULL),
(3072, 65, 21, 'solusi inovatif yang bisa dilakukan seperti penggunaan sensor yang tahan lama. Mengganti sensor yang ada dengan jenis sensor yang lebih tahan lama dan memiliki umur pakai yang lebih panjang. Beberapa jenis sensor yang dapat dipertimbangkan antara lain sensor elektrokimia, sensor optik, atau sensor berbasis nanomaterial.\r\n', NULL, NULL, NULL, NULL, '2025-02-16 16:47:52', NULL),
(3073, 89, 21, 'rancangan solusi yang bisa dilakukan yaitu melakukan penelitian dan pengujian terhadap berbagai jenis sensor untuk menentukan sensor yang paling sesuai untuk mendeteksi boraks dengan akurasi dan daya tahan yang optimal.\r\n', NULL, NULL, NULL, NULL, '2025-02-16 16:47:52', NULL),
(3074, 67, 21, NULL, 'e6fa8d0280993f2de9422a97796203e6.pdf', NULL, NULL, NULL, '2025-02-16 16:47:52', NULL),
(3075, 2, 70, 'Masalah utama yang terlihat adalah kesulitan petani mengalirkan air dari sungai menuju lahan pertanian karena posisi lahan lebih tinggi daripada sumber air. Untuk mengatasi hal tersebut petani masih bergantung pada pompa diesel yang membutuhkan bahan bakar sehingga biaya operasional menjadi tinggi dan kurang ramah lingkungan.', NULL, NULL, 95, 'sudah sangat baik', '2025-05-02 16:26:09', '2026-07-28 00:09:12'),
(3076, 4, 70, 'Masalah terjadi karena adanya perbedaan ketinggian antara sumber air dan lahan pertanian sehingga air sulit mengalir. Selain itu, belum tersedia teknologi irigasi yang memanfaatkan energi terbarukan sehingga petani masih menggunakan pompa berbahan bakar fosil.', NULL, NULL, 95, 'Kerja yang sudah baik, namun masih bisa digali lagi penyebabnya', '2025-05-02 16:26:09', '2026-07-28 00:09:12'),
(3077, 6, 70, 'Distribusi air ke lahan pertanian yang letaknya lebih tinggi dari sumber air menghadapi tantangan besar karena aliran air secara alami mengikuti gravitasi, sehingga diperlukan teknologi tambahan seperti pompa air. Namun, penggunaan pompa diesel sering mengalami kendala seperti biaya bahan bakar yang tinggi dan perawatan yang kurang memadai. Selain itu, mengairi lahan yang jauh dari sumber air juga membutuhkan infrastruktur irigasi yang kompleks dan biaya operasional yang tinggi, yang jika tidak tersedia, akan menyulitkan distribusi air secara merata.\r\n\r\nPermasalahan serupa dijelaskan dalam artikel “Permasalahan Sumber Daya Air dalam Pengelolaan Terpadu Daerah Irigasi Deras II Kabupaten Musi Rawas” oleh Yunan Hamdani dalam Jurnal Teknik Sipil UNPAL, Vol. 8 No. 2, November 2018. Dalam artikel tersebut disebutkan bahwa keterbatasan air akibat pengambilan di hulu serta kerusakan jaringan irigasi menyebabkan distribusi air menjadi tidak merata, terutama di wilayah hilir, serta sulitnya pemeliharaan sistem irigasi yang rusak atau tidak berfungsi.\r\n\r\nSumber:\r\nHamdani, Yunan. (2018). Permasalahan Sumber Daya Air dalam Pengelolaan Terpadu Daerah Irigasi Deras II Kabupaten Musi Rawas. Jurnal Teknik Sipil UNPAL, Vol. 8 No. 2, hlm. 112–117.', NULL, NULL, 95, 'Kerja yang baik', '2025-05-02 16:26:09', '2026-07-28 00:09:12'),
(3078, 5, 70, '', '7e5440b0d1bfbe85814d7b3e13ec350d.pdf', NULL, 93, 'Kerja yang baik, referensi bisa lebih diperkuat lagi', '2025-05-02 16:26:09', '2026-07-28 00:09:12'),
