(3620, 17, 55, 'operan 1 1 = \r\nSDL 2 pcs = \r\noperan 1 1\\2 = \r\nselotip = \r\ndouble nipple 1/2 1 pcs = \r\ndop2=  \r\npipa 2 inch 30 cm = \r\nSelang 1/2 =\r\nSambungan selang=\r\nSdd= \r\nLem pipa = \r\nKlep tusen = \r\nCheck valve= ', NULL, NULL, NULL, NULL, '2025-06-24 18:31:32', NULL),
(3621, 18, 55, 'inovasi dari sumber yang kami sebagai referensi merancang pompa hidram dari video yang kami lihat dimana katup yang digunakan pada video menggunakan botol sedangkan pada pompa hidram yang kami rancang katup nya menggunakan paralon,', NULL, NULL, NULL, NULL, '2025-06-24 18:31:32', NULL),
(3622, 76, 55, 'operan 1 1 = 17k\r\nSDL 2 pcs = 12k\r\noperan 1 1\\2 = 6k\r\nselotip = 4k\r\ndouble nipple 1/2 1 pcs = 4k\r\ndop2=  5k\r\npipa 2 inch 30 cm = 5k\r\nSelang 1/2 =13k\r\nSambungan selang=10k\r\nSdd= 4k\r\nLem pipa = 10k\r\nKlep tusen = 40 k\r\nCheck valve= 101 k\r\ntotal:270.000', NULL, NULL, NULL, NULL, '2025-06-24 18:31:32', NULL),
