(4002, 17, 52, 'Nomor 2\r\n\r\n1. Tabung udara\r\n2. Katup penghantar\r\n3. Check Valve\r\n4. Pipa 1 inch \r\n5. selang', NULL, NULL, NULL, NULL, '2025-07-13 22:24:23', NULL),
(4003, 18, 52, 'inovasi dari sumber yang kami sebagai referensi merancang pompa hidram dari video yang kami lihat dimana katup yang digunakan pada video menggunakan botol sedangkan pada pompa hidram yang kami rancang katup nya menggunakan paralon,', NULL, NULL, NULL, NULL, '2025-07-13 22:24:23', NULL),
(4004, 76, 52, 'operan 1 1 = 17k\r\nSDL 2 pcs = 12k\r\noperan 1 1\\2 = 6k\r\nselotip = 4k\r\ndouble nipple 1/2 1 pcs = 4k\r\ndop2=  5k\r\npipa 2 inch 30 cm = 5k\r\nSelang 1/2 =13k\r\nSambungan selang=10k\r\nSdd= 4k\r\nLem pipa = 10k\r\nKlep tusen = 40 k\r\nCheck valve= 101 k\r\nPipa T = 20k\r\nPipa 1 inch = 20 k\r\nTotal 271.000', NULL, NULL, NULL, NULL, '2025-07-13 22:24:23', NULL),
