INSERT INTO `tb_jawaban_essai` (`id_jawaban_essai`, `id_soal`, `id_user`, `jawaban_text`, `jawaban_file`, `jawaban_gambar`, `nilai`, `feedback`, `created_at`, `updated_at`) VALUES
(4011, 20, 80, 'Tujuan nya yaitu Meningkatkan pemahaman tentang prinsip kerja pompa hidram sebagai teknologi yang digunakan untuk pemanfaatan energi air tanya menggunakan listrik, yang menjadi solusi ramah lingkungan, dan menumbuhkan kerja sama anggota kelompok.', NULL, NULL, NULL, NULL, '2025-07-13 22:34:22', NULL),
(4012, 21, 80, 'operan 11 SDL 2 pcs operan 1 1\\2 selotip double nipple 1/21 pcs dope pipa 2 inch 30 cm Selang 1/2 Sambungan selang Sdd Lem pipa Klep tusen Check valve Pipa T Pipa 1 inci', NULL, NULL, NULL, NULL, '2025-07-13 22:34:22', NULL),
(4013, 22, 80, 'Perencanaan Sistem Aliran Pompa akan terdiri dari Pipa masukan (drive pipe) dari sumber air (mengalir menurun) Katup limbah (terletak horizontal di bagian ujung bawah) Engineerin Tabung udara (berdiri vertikal) Katup satu arah menuju pipa ke penampungan 3. Perakitan Komponen A. Rangka Dasar (Horizontal) Potong pipa sepanjang 40-50 cm. Pasang Evaluate sambungan Tidi tengahnya Salah satu sisi untuk katup Himbah Satu sisi ke drive pipe Idani sumber air) Arah ke atas (T cabang vertikall-tabung udara B Tabung Udara Gunakan Evaluate pipals inci, panjang 30-40 cm-Tutup ujung atasnya rapat dengan dop tem PVC Fungsi meredam tekanan dan Evaluate menjaga aturan stabil C. Katup Satu Arah Pasang setelah Tike arah output air ipipa pengeluaran) Sambungkan ke pipa 1 ind yang akan mengalirkan air ke tempat lebih tinggi', NULL, NULL, NULL, NULL, '2025-07-13 22:34:22', NULL),
(4014, 23, 80, 'Langkah langkah yang kami lakukan adalah merangkai alat alatnya.Setelah semua bagian pompa terpasang, langkah pertama yang dilakukan adalah memeriksa setiap sambungan pipa dan komponen lainnya. Tujuannya adalah memastikan tidak ada kebocoran dan semua bagian terpasang dengan benar. Air dari sumber seharusnya mengalir melalui pipa masuk (drive pipe) menuju ke sistem pompa. Setelah itu kami mengamati bagian katup apakah Ada bunyi ketukan dari katup limbah atau tidak yang menandakan bahwa pompa bekerja', NULL, NULL, NULL, NULL, '2025-07-13 23:05:36', NULL),
(4015, 25, 80, 'menurut kelompok kami dari percobban pertama alat desain yang kami gunakan tidak perlu ditingkatkan atau menambah alat alat karena pada desain kami sudah cukup berfungsi karena permasalahan hanya dari aliran', NULL, NULL, NULL, NULL, '2025-07-13 23:05:36', NULL),
(4016, 26, 80, 'Setelah melakukan uji coba pertama, pompa hidram yang dibuat ternyata belum bisa bekerja dengan baik. Air dari sumber memang mengalir, tapi tekanannya kurang kuat sehingga tidak mampu mendorong air naik. Hal ini membuat pompa tidak bisa berfungsi secara maksimal.\r\n\r\nMelihat masalah itu, kami melakukan perubahan pada rancangan awal, yaitu dengan menambahkan bendungan kecil di sumber air. Bendungan ini  fungsinya untuk menampung air lebih banyak sebelum dialirkan ke pompa. Dengan adanya bendungan, air yang masuk ke pipa menjadi lebih deras dan tekanan air pun meningkat.', NULL, NULL, NULL, NULL, '2025-07-13 23:05:36', NULL),
(4017, 29, 80, 'Pada uji coba pertama, pompa hidram belum bisa bekerja dengan baik. Air memang mengalir dari sumber, tapi tekanannya kurang kuat. Akibatnya, air tidak bisa naik  seperti yang diharapkan. Pompa tidak bisa memompa air karena dorongan dari air terlalu lemah.\r\n\r\nSetelah itu, dilakukan uji coba kedua dengan cara menambahkan bendungan kecil di dekat sumber air. Bendungan ini membantu menampung air lebih banyak dan membuat aliran air jadi lebih deras. Hasilnya, tekanan air jadi lebih kuat dan pompa bisa bekerja dengan baik.\r\n\r\nKesimpulannya, uji coba pertama gagal karena tekanan air terlalu lemah. Setelah ditambah bendungan, pompa bisa bekerja dan air berhasil dipompa ke tempat yang lebih tinggi tanpa listrik.', NULL, NULL, NULL, NULL, '2025-07-13 23:05:36', NULL),
(4018, 77, 80, 'dari uji coba 1 alat pompa hidram kami tidak berhasil dikarenakan aliran air nya kurang deras sehingga kami memutuskan mencoba menggunkan air keran untuk melakukan percobaan tersebut  berhasil menaikan aliran  sehingga  dapat  diketahui  alat pompa hidram bisa berfungsi', NULL, NULL, NULL, NULL, '2025-07-13 23:05:36', NULL),
(4019, 24, 80, NULL, '6210ad667e0eba688d83ef5af112742b.docx', NULL, NULL, NULL, '2025-07-13 23:05:36', NULL),
(4020, 28, 80, NULL, 'c65eac984ad4fb9f2119c685ddd10283.docx', NULL, NULL, NULL, '2025-07-13 23:05:36', NULL),
(4021, 38, 76, 'Masalah utamanya makanan yang mengandung boraks tidak baik bagi kesehatan dan dapat berjangka panjang pada kesehatan, kemudian kurang nya pengetahuan masyarakat mengenai makanan yang mengandung boraks', NULL, NULL, NULL, NULL, '2025-07-13 23:56:56', NULL),
(4022, 39, 76, 'Masalah tersebut dapat terjadi Karena kurangnya kesadaran pedagang yang hanya memikirkan keuntungan yang besar dan kurangnya pengetahuan masyarakat mengenai makanan yang mengandung boraks dan bahaya yang ditimbulkan oleh makanan yang mengandung boraks', NULL, NULL, NULL, NULL, '2025-07-13 23:56:56', NULL),
(4023, 40, 76, 'Boraks adalah senyawa seperti kaca berwarna putih yang tidak beraroma dan stabil pada suhu \r\nkamar. Boraks tergolong bahan berbahaya karena berdampak buruk bagi kesehatan bila dikonsumsi \r\noleh konsumen. Meskipun boraks berbahaya bagi kesehatan, namun boraks masih sering dimanfaatkan \r\noleh masyarakat sebagai bahan tambahan makanan, karena selain berfungsi sebagai bahan tambahan, \r\nboraks juga dapat bekerja pada permukaan makanan sehingga lebih kenyal dan enak dinikmati oleh \r\npembeli', NULL, NULL, NULL, NULL, '2025-07-13 23:56:56', NULL),
(4025, 91, 76, 'Boraks dalam makanan dapat menyebabkan dampak kesehatan jangka panjang yang serius, seperti kerusakan hati dan ginjal, gangguan saraf, infertilitas, hingga kanker (hati dan usus besar). Konsumsi terus-menerus juga dapat menimbulkan gejala awal seperti mual, muntah, diare, dan lemas, serta risiko gagal ginjal dan kematian jika dosisnya tinggi. Karena boraks bersifat racun dan karsinogenik, penggunaannya dalam makanan sudah dilarang secara resmi.', NULL, NULL, NULL, NULL, '2025-07-13 23:56:56', NULL),
(4027, 41, 76, NULL, 'b021ba19e24554692e79c3d3e15e4dd1.pdf', NULL, NULL, NULL, '2025-07-13 23:56:56', NULL),
