INSERT INTO `tb_jawaban_essai` (`id_jawaban_essai`, `id_soal`, `id_user`, `jawaban_text`, `jawaban_file`, `jawaban_gambar`, `nilai`, `feedback`, `created_at`, `updated_at`) VALUES
(5446, 98, 77, 'Alat\r\nGergaji pipa/PVC cutter\r\nTang kombinasi\r\nKunci inggris atau kunci pipa\r\nObeng (+/-)\r\nBor tangan (jika diperlukan untuk membuat lubang dudukan)\r\nMeteran/penggaris\r\nLem tembak atau alat perekat\r\nKuas (untuk aplikasi lem PVC bila diperlukan)\r\nWadah pengujian (ember/bak air)\r\nAlat ukur volume air (gelas ukur)\r\nStopwatch untuk mengukur debit air hasil pompa\r\nBahan\r\nPipa PVC berbagai ukuran (misalnya PVC 1–2 inch untuk badan pompa dan pipa penghubung)\r\nSambungan pipa PVC (sok, elbow, tee, reducer)\r\nKatup limbah (waste valve)\r\nKatup satu arah (check valve)\r\nTabung udara (air chamber) dari pipa PVC atau botol bertekanan yang sesuai\r\nPipa input/sumber air (drive pipe)\r\nPipa keluaran (delivery pipe)\r\nLem PVC\r\nSeal tape untuk mencegah kebocoran sambungan\r\nBaut, mur, atau klem pengikat\r\nSumber air (bak penampung atau aliran air)', NULL, NULL, 90, 'Hasil kerja ananda sudah baik', '2026-07-28 00:09:12', '2026-07-28 00:09:12'),
(5447, 96, 24, 'Kelompok kami memilih desain prototipe pompa hidram karena alat ini merupakan teknologi sederhana yang dapat memanfaatkan energi aliran air tanpa menggunakan bahan bakar atau energi listrik. Desain ini sesuai untuk diterapkan pada daerah pertanian yang memiliki keterbatasan akses listrik, tetapi memiliki sumber air dengan perbedaan ketinggian tertentu.\r\n\r\nPompa hidram dipilih karena memiliki beberapa keunggulan, yaitu konstruksi yang relatif sederhana, biaya pembuatan yang rendah, mudah dirawat, dan dapat bekerja secara otomatis menggunakan prinsip tekanan air (water hammer effect). Dengan memanfaatkan energi potensial dan kinetik dari aliran air, pompa hidram mampu mengalirkan sebagian air menuju lokasi yang lebih tinggi tanpa memerlukan pompa bermotor.\r\n\r\nDesain prototipe ini dapat menjadi solusi terhadap permasalahan distribusi air pada sistem irigasi pertanian karena mampu membantu mengalirkan air dari sumber air seperti sungai, saluran irigasi, atau mata air menuju lahan pertanian yang memiliki posisi lebih tinggi. Dengan demikian, ketersediaan air untuk tanaman dapat lebih terjamin, terutama pada wilayah yang mengalami kendala distribusi air akibat jarak atau perbedaan elevasi lahan.\r\n\r\nSelain itu, penggunaan pompa hidram mendukung konsep teknologi ramah lingkungan karena tidak menghasilkan emisi dan mengurangi ketergantungan terhadap energi listrik atau bahan bakar.', NULL, NULL, 95, 'Hasil kerja ananda sudah baik', '2026-07-28 00:09:12', '2026-07-28 00:09:12'),
