INSERT INTO `tb_jawaban_essai` (`id_jawaban_essai`, `id_soal`, `id_user`, `jawaban_text`, `jawaban_file`, `jawaban_gambar`, `nilai`, `feedback`, `created_at`, `updated_at`) VALUES
(5901, 43, 23, 'Penggunaan boraks sebagai bahan tambahan makanan telah lama dilakukan, antara lain dalam pembuatan krupuk gendar. Boraks oleh pedagang dikenal dengan nama bleng, cetitet, puli, atau obat gendar (bahasa Jawa). Dari hasil penelitian dengan uji kualitatif sampel mie kuning basah yang diambil di pasar-pasar tradisional Pekanbaru didapatkan hasil pada ketiga metode yang digunakan menunjukkan semua sampel mie basah positif mengandung boraks kecuali sampel dari pasar Z. Pada uji kualitatif sampel bakso yang diambil di pasar–pasar tradisional Pekanbaru didapatkan hasil pada ketiga metode yang digunakan menunjukkan semua sampel bakso negatif mengandung boraks kecuali sampel dari pasar X. Pada uji kualitatif sampel lontong yang diambil di pasar–pasar tradisional Pekanbaru didapatkan hasil pada ketiga metode yang digunakan menunjukkan hanya satu sampel positif mengandung boraks yaitu sampel dari pasar X.', NULL, NULL, 85, '', '2026-07-28 02:01:24', '2026-07-28 02:01:24'),
(5902, 43, 38, 'Penggunaan boraks sebagai bahan tambahan makanan telah lama dilakukan, antara lain dalam pembuatan krupuk gendar. Boraks oleh pedagang dikenal dengan nama bleng, cetitet, puli, atau obat gendar (bahasa Jawa). Dari hasil penelitian dengan uji kualitatif sampel mie kuning basah yang diambil di pasar-pasar tradisional Pekanbaru didapatkan hasil pada ketiga metode yang digunakan menunjukkan semua sampel mie basah positif mengandung boraks kecuali sampel dari pasar Z. Pada uji kualitatif sampel bakso yang diambil di pasar–pasar tradisional Pekanbaru didapatkan hasil pada ketiga metode yang digunakan menunjukkan semua sampel bakso negatif mengandung boraks kecuali sampel dari pasar X. Pada uji kualitatif sampel lontong yang diambil di pasar–pasar tradisional Pekanbaru didapatkan hasil pada ketiga metode yang digunakan menunjukkan hanya satu sampel positif mengandung boraks yaitu sampel dari pasar X.', NULL, NULL, 85, '', '2026-07-28 02:01:24', '2026-07-28 02:01:24'),
