INSERT INTO `tb_test_unity` (`id_test_unity`, `id_user`, `indikator_soal`, `practice`, `pertanyaan`, `test_type`, `jawaban`, `nilai`, `feedback`) VALUES
(1, 16, 'alal1', 'llala', 'alalla\r\n', NULL, 'alala', 70, NULL),
(2, 16, 'lili', 'lili', 'lilolo', NULL, 'llilililili', 70, NULL),
(172, 12, 'Analisis keuntungan dan kerugian dari teknologi yang ada. Mengidentifikasi kelebihan dan kekurangan teknologi yang ada. ', 'Understanding technological principles', '1', NULL, 'aa, ', 20, ''),
(173, 12, 'Pilih teknologi yang tepat untuk memecahkan masalah masyarakat. Menjelaskan alasan mengapa teknologi yang dipilih merupakan solusi terbaik dibandingkan alternatif lainnya. ', 'Developing solutions and achieving goals	Pilih teknologi yang tepat untuk memecahkan masalah masyarakat. Menjelaskan alasan mengapa teknologi yang dipilih merupakan solusi terbaik dibandingkan alternatif lainnya.	Perhatikan pengumuman di bawah ini     Pak', '2', NULL, 'a, a, ', NULL, NULL),
(174, 12, 'Jelaskan kepada audiens tertentu bagaimana sesuatu bekerja Memanfaatkan informasi digital untuk menjelaskan bagaimana teknologi pendeteksi makanan mengandung borak bekerja. ', 'Communication and collaborating', '9', 'posttest', 'Ya, a, a, ', NULL, NULL),
(175, 12, 'Buat presentasi multimedia. Mengorganisasi konten presentasi secara jelas, ringkas, dan sesuai dengan topik yang diberikan. ', 'Communication and collaborating', '3', NULL, 'a, aa, aa, a, aa, a, ', NULL, NULL),
(176, 12, 'Menghasilkan desain atau produk alternatif Merancang produk alternatif yang lebih aman dan dapat menggantikan penggunaan borak dalam makanan. ', 'Developing solutions and achieving goals', '5', 'posttest', 'aa, a, a, ', NULL, NULL),
(177, 12, 'Membenarkan pilihan alat untuk tujuan tertentu. Mengidentifikasi media digital yang tepat (artikel, video, tutorial, e-book, aplikasi, dll.) terkait makanan mengandung borak. ', 'Understanding technological principles', '7', 'posttest', 'a, a, ', NULL, NULL),
(178, 12, 'Mencari media dan sumber daya digital. Menemukan sumber daya digital yang relevan terkait makanan mengandung borak. ', 'Developing solutions and acheiving goals', '8', 'posttest', 'a, a, ', NULL, NULL),
(179, 12, 'Mewakili data dalam grafik, tabel, dan model. Mengorganisasi data hasil deteksi borak dari beberapa sampel makanan ke dalam bentuk tabel yang jelas dan sistematis. ', 'Communication and collaborating', '6', 'posttest', 's, d, ', NULL, NULL),
(180, 12, 'Menjelaskan fitur suatu sistem atau proses. Menggambarkan alur proses kerja dari awal hingga akhir penggunaan alat pendeteksi borak. ', 'Understanding technological principles', '4', 'posttest', 'a-a-a-a-a-a-', NULL, NULL),
